comms.text:
@1 וְאִתְפְּלֵג קֹרַח בַּר יִצְהָר בַּר קְהָת בַּר לֵוִי וְדָתָן וַאֲבִירָם בְּנֵי אֱלִיאָב וְאוֹן בַּר פֶּלֶת בְּנֵי רְאוּבֵן:
@2 וְקָמוּ לְאַפֵּי משֶׁה וְגֻבְרַיָא מִבְּנֵי יִשְׂרָאֵל מָאתָן וְחַמְשִׁין רַבְרְבֵי כְנִשְׁתָּא מְעַרְעֵי זְמַן אֱנָשִׁין דִשְׁמָא:
@3 וְאִתְכְּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן וַאֲמָרוּ לְהוֹן סַגִי לְכוֹן אֲרֵי כָל כְּנִשְׁתָּא כֻּלְהוֹן קַדִישִׁין וּבֵינֵיהוֹן שַׁרְיָא שְׁכִנְתָּא דַיְיָ וּמָא דֵין אַתּוּן מִתְרַבְרְבִין עַל קְהָלָא דַיְיָ:
@4 וּשְׁמַע משֶׁה וּנְפַל עַל אַפּוֹהִי:
@5 וּמַלִיל עִם קֹרַח וְעִם כָּל כְּנִשְׁתֵּהּ לְמֵימַר בְּצַפְרָא וִיהוֹדַע יְיָ יָת דְכָשַׁר לֵהּ וְיָת דְקַדִישׁ וִיקָרֵב לָקֳדָמוֹהִי וְיָת דִי יִתְרְעֵי בֵהּ יְקָרֵב לְשִׁמוּשֵׁהּ:
@6 דָא עַבִידוּ סָבוּ לְכוֹן מַחְתְּיָן קֹרַח וְכָל כְּנִשְׁתֵּהּ:
@7 וְהָבוּ בְהוֹן אֵשָׁתָא וְשַׁוִיאוּ עֲלֵיהוֹן קְטוֹרֶת בּוּסְמִין קֳדָם יְיָ מְחַר וִיהֵי גַבְרָא דְיִתְרְעֵי יְיָ הוּא קַדִישּׁ סַגִי לְכּוֹן בְּנֵי לֵוִי:
@8 וַאֲמַר משֶׁה לְקֹרַח שְׁמָעוּ כְעַן בְּנֵי לֵוִי:
@9 הַזְעֵר לְכוֹן אֲרֵי אַפְרֵשׁ אֱלָהָא דְיִשְׂרָאֵל יָתְכוֹן מִכְּנִשְׁתָּא דְיִשְׂרָאֵל לְקֳרָבָא יָתְכוֹן קֳדָמוֹהִי לְמִפְלַח יָת פּוּלְחַן מַשְׁכְּנָא דַיְיָ וּלְמֵקַם קֳדָם כְּנִשְׁתָּא לְשַׁמָשׁוּתְהוֹן:
@10 וְקָרֵב יָתָךְ וְיַת כָּל אֲחָךְ בְּנֵי לְוֵי עִמָךְ וּכְעַן אַתּוּן בָּעָן אַף כְּהוּנְתָא רַבְּתָא:
@11 בְּכֵן אַתְּ וְכָל כְּנִשְׁתָּךְ דְאִזְדַמַנְתּוּן עַל יְיָ וְאַהֲרֹן מַה הוּא אֲרֵי אִתְרַעַמְתּוּן עֲלוֹהִי:
@12 וּשְׁלַח משֶׁה לְמִקְרֵי לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב וַאֲמָרוּ לָא נִסָק:
@13 הַזְעֵיר אֲרֵי אַסֵקְתָּנָא מֵאַרְעָא עָבְדָא חֲלַב וּדְבָשׁ לְקַטָלוּתָנָא בְּמַדְבְּרָא אֲרֵי אִתְרַבְרַבְתְּ עֲלָנָא אַף אִתְרַבְרָבָא:
@14 בְּרַם לָא לְאַרְעָא עָבְדָא חֲלָב וּדְבָשׁ אַעֵלְתָּנָא וִיהַבְתְּ לָנָא אַחֲסָנַת חַקְלִין וְכַרְמִין הַעֵינֵי גֻבְרַיָא הָאִינוּן תְּשַׁלַח לְעַוָרָא לָא נִסָק:
@15 וּתְקֵף לְמשֶׁה לַחֲדָא וַאֲמַר קֳדָם יְיָ לָא תְקַבֵּל בְּרַעֲוָא קוּרְבַּנְהוֹן לָא חֲמָרָא דְחַד מִנְהוֹן שְׁחָרִית וְלָא אַבְאֵישִׁית יַת חָד מִנְהוֹן:
@16 וַאֲמַר משֶׁה לְקֹרַח אַתְּ וְכָל כְּנִשְׁתָּךְ הֱווֹ זְמִינִין לָקֳדָם יְיָ אַתְּ וְאִינוּן וְאַהֲרֹן מְחָר:
@17 וּסְבוּ גְבַר מַחְתִּיתֵיהּ וּתְשַׁווּן עֲלֵיהוֹן קְטוֹרֶת בּוּסְמִין וְתִקָרְבוּן קֳדָם יְיָ גְבַר מַחְתִּיתֵיהּ מָאתָן וְחַמְשִׁין מַחְתְּיָן וְאַתְּ וְאַהֲרֹן גְבַר מַחְתִּיתֵהּ:
@18 וּנְסִיבוּ גְבַר מַחְתִּיתֵהּ וִיהָבוּ עֲלֵיהוֹן אֵשָׁתָא וְשַׁוִיאוּ עֲלֵיהוֹן קְטֹרֶת בּוּסְמִין וְקָמוּ בִּתְרַע מַשְׁכַּן זִמְנָא וּמשֶׁה וְאַהֲרֹן:
@19 וְאַכְנֵשׁ עֲלֵיהוֹן קֹרַח יָת כָּל כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא וְאִתְגְלֵי יְקָרָא דַיְיָ לְכָל כְּנִשְׁתָּא:
@20 וּמַלֵיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@21 אִתְפְּרָשׁוּ מִגוֹ כְּנִשְׁתָּא הָדָא וֶאֱשֵׁיצֵי יַתְהוֹן כְּשָׁעָה:
@22 וּנְפָלוּ עַל אַפֵּיהוֹן וַאֲמָרוּ אֵל אֱלָהָא רוּחַיָא לְכָל בִּשְׂרָא גַבְרָא חָד יֵיחוֹב וְעַל כָּל כְּנִשְׁתָּא יְהֵי רוּגְזָא:
@23 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@24 מַלֵל עִם כְּנִשְׁתָּא לְמֵימָר אִסְתַּלָקוּ מִסְחוֹר סְחוֹר לְמַשְׁכְּנָא דְקֹרַח דָתָן וַאֲבִירָם:
@25 וְקָם משֶׁה וַאֲזַל לְוַת דָתָן וַאֲבִירָם וַאֲזָלוּ בַּתְרוֹהִי סָבֵי יִשְׂרָאֵל:
@26 וּמַלֵיל עִם כְּנִשְׁתָּא לְמֵימָר זוּרוּ כְעַן מֵעִלַוֵי מַשְׁכְּנֵי גֻבְרַיָא חַיָיבַיָא הָאִלֵין וְלָא תְקָרְבוּן בְּכָל דִי לְהוֹן דִלְמָא תִלְקוּן בְּכָל חוֹבֵיהוֹן:
@27 וְאִסְתַּלָקוּ מֵעִלַוֵי מַשְׁכְּנָא דְקֹרַח דָתָן וַאֲבִירָם מִסְחוֹר סְחוֹר וְדָתָן וַאֲבִירָם נְפָקוּ קַיְימִין בִּתְרַע מַשְׁכְּנֵיהוֹן וּנְשֵׁיהוֹן וּבְנֵיהוֹן וְטַפְלְהוֹן:
@28 וַאֲמַר משֶׁה בְּדָא תִדְעוּן אֲרֵי יְיָ שַׁלְחַנִי לְמֶעְבַּד יָת כָּל עוֹבָדַיָא הָאִלֵין אֲרֵי לָא מֵרְעוּתִי:
@29 אִם כְּמוֹתָא דְכָל אֱנָשָׁא יְמוּתוּן אִלֵין וּסְעָרָא דְכָל אֱנָשָׁא יִסְתְּעַר עֲלֵיהוֹן לָא יְיָ שַׁלְחַנִי:
@30 וְאִם בְּרִיאָה יִבְרֵי יְיָ וּפְתָחַת אַרְעָא יָת פּוּמַהּ וְתִבְלַע יַתְהוֹן וְיַת כָּל דִי לְהוֹן וְיֶחֱתוּן כַּד חַיִין לִשְׁאוֹל וְתִדְעוּן אֲרֵי אַרְגִיזוּ גוּבְרַיָא הָאִלֵין קֳדָם יְיָ:
@31 וַהֲוָה כַּד שֵׁיצֵי לְמַלָלָא יָת כָּל פִּתְגָמַיָא הָאִלֵין וְאִתְבְּזָעַת אַרְעָא דִי תְּחוֹתֵיהוֹן:
@32 וּפְתָחַת אַרְעָא יָת פּוּמָהּ וּבְלָעַת יַתְהוֹן וְיַת אֱנַשׁ בָּתֵּיהוֹן וְיַת כָּל אֱנָשָׁא דִי לְקֹרַח וְיַת כָּל קִנְיָנָא:
@33 וּנְחָתוּ אִינוּן וְכָל דִי לְהוֹן כַּד חַיִין לִשְׁאוֹל וַחֲפַת עֲלֵיהוֹן אַרְעָא וַאֲבָדוּ מִגוֹ קְהָלָא:
@34 וְכָל יִשְׂרָאֵל דִי בְסַחֲרָנֵיהוֹן עֲרָקוּ לְקַלְהוֹן אֲרֵי אֲמָרוּ דִלְמָא תִבְלְעִנָנָא אַרְעָא:
@35 וְאֶשָׁתָא נְפָקַת מִן קֳדָם יְיָ וַאֲכָלַת יָת מָאתָן וְחַמְשִׁין גַבְרָא מְקַרְבֵי קְטוֹרֶת בּוּסְמַיָא:
@36 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@37 אֱמַר לְאֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא וְיַפְרֵשׁ יָת מַחְתְּיָתָא מִבֵּין יְקִידַיָא וְיָת אֶשָׁתָא יַרְחִיק לְהָלָא אֲרֵי אִתְקַדָשׁוּ:
@38 יָת מַחְתְּיַת חַיָיבַיָא הָאִלֵין דְאִתְחַיְיבוּ בְּנַפְשָׁתֵיהוֹן וְיַעְבְּדוּן יַתְהוֹן טַסִין רְדִידִין חוֹפָאָה לְמַדְבְּחָא אֲרֵי קָרֵבֻנוּן קֳדָם יְיָ וְאִתְקַדָשׁוּ וִיהֶוְיָן לְאָת לִבְּנֵי יִשְׂרָאֵל:
@39 וּנְסִיב אֶלְעָזָר כַּהֲנָא יָת מַחְתְּיָתָא דִנְחָשָׁא דְקָרִיבוּ יוֹקִידַיָא וְרַדִידֻנוּן חוֹפָאָה לְמַדְבְּחָא:
@40 דָכְרָנָא לִבְנֵי יִשְׂרָאֵל בְּדִיל דִי לָא יִקְרַב גְבַר חִלוֹנַי דִי לָא מִזַרְעָא דְאַהֲרֹן הוּא לְאַסָקָא קְטוֹרֶת בּוּסְמִין קֳדָם יְיָ וְלָא יְהֵי כְקֹרַח וְכִכְנִשְׁתֵּיהּ כְּמָא דִי מַלֵיל יְיָ בִּידָא דְמשֶׁה לֵיהּ:
@41 וְאִתְרַעֲמוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִיוֹמָא דְבַתְרוֹהִי עַל משֶׁה וְעַל אַהֲרֹן לְמֵימָר אַתּוּן גְרַמְתּוּן דְמִית עַמָא דַיְיָ:
@42 וַהֲוָה בְּאִתְכַּנָשׁוּת כְּנִשְׁתָּא עַל משֶׁה וְעַל אַהֲרֹן וְאִתְפְּנִיאוּ לְמַשְׁכַּן זִמְנָא וְהָא חֲפָהִי עֲנָנָא וְאִתְגְלִי יְקָרָא דַיְיָ:
@43 וְעָאל משֶׁה וְאַהֲרֹן לָקֳדָם מַשְׁכַּן זִמְנָא:
@44 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@45 אִתְפְרָשׁוּ מִגוֹ כְּנִשְׁתָּא הָדָא וְאֱשֵׁיצֵי יָתְהוֹן כְּשָׁעָה וּנְפָלוּ עַל אַפֵּיהוֹן:
@46 וַאֲמַר משֶׁה לְאַהֲרֹן סַב יָת מַחְתִּיתָא וְהַב עֲלַהּ אֶשָׁתָא מֵעִלָוֵי מַדְבְּחָא וְשַׁו קְטוֹרֶת בּוּסְמַיָא וְאוֹבִיל בִּפְרִיעַ לִכְנִשְׁתָּא וְכַפֵּר עֲלֵיהוֹן אֲרֵי נְפַק רָגְזָא מִן קֳדָם יְיָ שָׁרֵי מוֹתָנָא:
@47 וּנְסֵיב אַהֲרֹן כְּמָא דְמַלֵיל משֶׁה וּרְהַט לְגוֹ קְהָלָא וְהָא שָׁרֵי מוֹתָנָא בְּעַמָא וִיהַב יָת קְטּוֹרֶת בּוּסְמַיָא וְכַפֵּר עַל עַמָא:
@48 וְקָם בֵּין מֵתַיָא וּבֵין חַיַיָא וְאִתְכְּלִי מוֹתָנָא:
@49 וַהֲווֹ דְמִיתוּ בְּמוֹתָנָא אַרְבַּעַת עֲשַׂר אַלְפִין וּשְׁבַע מְאָה בַּר מִדְמִיתוּ עַל פְּלֻגְתָּא דְקֹרַח:
@50 וְתָב אַהֲרֹן לְמשֶׁה לִתְרַע מַשְׁכַּן זִמְנָא וּמוֹתָנָא אִתְכְּלִי:
@51 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@52 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְסַב מִנְהוֹן חוּטְרָא חוּטְרָא לְבֵית אַבָּא מִן כָּל רַבְרְבָנֵיהוֹן לְבֵית אֲבָהַתְהוֹן תְּרֵי עֲשַׂר חוּטְרִין גְבַר יָת שְׁמֵיהּ תִּכְתּוֹב עַל חוּטְרֵיהּ:
@53 וְיָת שְׁמָא דְאַהֲרֹן תִּכְתּוֹב עַל חוּטְרָא דְלֵוִי אֲרֵי חוּטְרָא חָד לְרֵישׁ בֵּית אֲבָהַתְהוֹן:
@54 וְתַצְנְעִינוּן בְּמַשְׁכַּן זִמְנָא קֳדָם סַהֲדוּתָא דִי אֲזַמִין מֵימְרִי לְכוֹן תַּמָן:
@55 וִיהֵי גַבְרָא דִי אִתְרְעֵי בֵּהּ חוּטְרֵיהּ יִנְעֵי וַאֲנִיחַ מִן קֳדָמַי יָת תּוּרְעֲמַת בְּנֵי יִשְׂרָאֵל דִי אִנוּן מִתְרַעֲמִין עֲלֵיכוֹן:
@56 וּמַלֵיל משֶׁה עִם בְּנֵי יִשְׂרָאֵל וִיהָבוּ לֵיהּ כָּל רַבְרְבָנֵיהוֹן חוּטְרָא לְרַבָּא חָד חוּטְרָא לְרַבָּא חָד לְבֵית אֲבָהַתְהוֹן תְּרֵי עֲשַׂר חוּטְרִין וְחוּטְרָא דְאַהֲרֹן בְּגוֹ חוּטְרֵיהוֹן:
@57 וְאַצְנַע משֶׁה יָת חוּטְּרַיָא קֳדָם יְיָ בְּמַשְׁכְּנָא דְסַהֲדוּתָא:
@58 וַהֲוָה בְּיוֹמָא דְבַתְרוֹהִי וְעַאל משֶׁה לְמַשְׁכְּנָא דְסַהֲדוּתָא וְהָא נְעָא חוּטְרָא דְאַהֲרֹן לְבֵית לְוֵי וְאַפֵּק לַבְלְבִין וְאָנֵץ נֵץ וְכָפֵית שִׁיגְדִין:
@59 וְאַפֵיק משֶׁה יָת כָּל חוּטְרַיָא מִן קֳדָם יְיָ לְוָת כָּל בְּנֵי יִשְׂרָאֵל וְאִשְׁתְּמוֹדָעוּ וּנְסִיבוּ גְבַר חוּטְרֵיהּ:
@60 וַאֲמַר יְיָ לְמשֶׁה אָתֵיב יַת חוּטְרָא דְאַהֲרֹן לְקֳדָם סַהֲדוּתָא לְמַטָרָא לְאָת לְעַמָא סַרְבָנָא וִיסוּפַן תּוּרְעֲמַתְהוֹן מִן קֳדָמַי וְלָא יְמוּתוּן:
@61 וַעֲבַד משֶׁה כְּמָא דִי פַקֵיד יְיָ יָתֵיה כֵּן עֲבָד:
@62 וַאֲמָרוּ בְּנֵי יִשְׂרָאֵל לְמשֶׁה לְמֵימָר הָא מִנָנָא קְטָלַת חַרְבָּא הָא מִנָנָא בְּלָעַת אַרְעָא וְהָא מִנָנָא דְמִיתוּ בְמוֹתָנָא:
@63 כֹּל דְקָרֵב מִקְרַב לְמַשְׁכְּנָא דַיְיָ מָאִית הָא אַנַחְנָא סַיְפִין לִמְמָת:
@64 וַאֲמַר יְיָ לְאַהֲרֹן אַתְּ וּבְנָךְ וּבֵית אֲבוּךְ עִמָךְ תְּסַלְחוּן עַל חוֹבֵי מַקְדְשָׁא וְאַתְּ וּבְנָךְ עִמָךְ תְּסַלְחוּן עַל חוֹבֵי כְּהוּנַתְכוֹן:
@65 וְאַף יָת אֲחָיךְ שִׁבְטָא דְלֵוִי שִׁבְטָא דַאֲבוּךְ קָרֵיב לְוָתָךְ וְיִתּוֹסְפוּן עֲלָךְ וִישַׁמְשׁוּנָךְ וְאַתְּ וּבְנָךְ עִמָךְ קֳדָם מַשְׁכְּנָא דְסַהֲדוּתָא:
@66 וְיִטְרוּן מַטַרְתָּךְ וּמַטְרַת כָּל מַשְׁכְּנָא בְּרַם לְמָנֵי קוּדְשָׁא וּלְמַדְבְּחָא לָא יִקְרְבוּן וְלָא יְמוּתוּן אַף אִינוּן אַף אַתּוּן:
@67 וְיִתּוֹסְפוּן עֲלָךְ וְיִטְרוּן יָת מַטְרַת מַשְׁכַּן זִמְנָא לְכָל פּוּלְחַן מַשְׁכְּנָא וְחִילוֹנֵי לָא יִקְרַב לְוָתְכוֹן:
@68 וְתִטְרוּן יָת מַטְרַת קוּדְשָׁא וְיָת מַטְרַת מַדְבְּחָא וְלָא יְהֵי עוֹד רוּגְזָא עַל בְּנֵי יִשְׂרָאֵל:
@69 וַאֲנָא הָא קְרֵיבִית יָת אֲחֵיכוֹן לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל לְכוֹן מַתְּנָא יְהִיבִין קֳדָם יְיָ לְמִפְלַח יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@70 וְאַתְּ וּבְנָךְ עִמָךְ תִּטְרוּן יָת כְּהוּנַתְכוֹן לְכָל פִּתְגַם מַדְבְּחָא וּלְמִגָיו לְפָרוּכְתָּא וְתִפְלְחוּן פוּלְחַן מַתְּנָא אֵיהַב יָת כְּהוּנַתְכוֹן וְחִילוֹנֵי דְיִקְרַב יִתְקְטֵיל:
@71 וּמַלֵיל יְיָ עִם אַהֲרֹן וַאֲנָא הָא יְהָבִית לָךְ יָת מַטְרַת אַפְרָשׁוּתָי לְכָל קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל לָךְ יְהַבְתִּינוּן לִרְבוּ וְלִבְנָךְ לִקְיָם עֲלָם:
@72 דֵין יְהֵי לָךְ מִקוֹדֶשׁ קוּדְשַׁיָא מוֹתַר מִן אֶשָׁתָא כָּל קוּרְבַּנְהוֹן לְכָל מִנְחַתְהוֹן וּלְכָל חַטְוַתְהוֹן וּלְכָל אֲשַׁמְהוֹן דִי יְתִיבוּן קֳדָמַי קוֹדֶשׁ קוּדְשִׁין דִילָךְ הִיא וְלִבְנָךְ:
@73 בְּקֹדֶשׁ קוּדְשִׁין תֵּיכְלוּנֵיהּ כָּל דְכוּרָא יֵיכוֹל יָתֵיהּ קוּדְשָׁא יְהֵי לָךְ:
@74 וְדֵין לָךְ אַפְרָשׁוּת מַתְּנַתְהוֹן לְכָל אֲרָמוּת בְּנֵי יִשְׂרָאֵל לָךְ יְהַבְתִּינוּן וְלִבְנָיךְ וְלִבְנְתָיךְ עִמָךְ לִקְיַם עֲלָם כָּל דִדְכֵי בְּבֵיתָךְ יֵיכוֹל יָתֵיהּ:
@75 כָּל טוּב מְשַׁח וְכָל טוּב חֲמַר וְעִבּוּר רֵאשִׁיתְהוֹן דִי יִתְּנוּן קֳדָם יְיָ לָךְ יְהַבְתִּינוּן:
@76 בִּכּוּרֵי כָּל דִי בְאַרְעֲהוֹן דִי יַיְתוּן קֳדָם יְיָ דִילָךְ יְהֵי כָּל דִדְכֵי בְּבֵיתָךְ יֵיכְלִנֵיהּ:
@77 כָּל חֶרְמָא בְּיִשְׂרָאֵל דִילָךְ יְהֵי:
@78 כָּל פְּתַח וַלְדָא לְכָל בִּשְׂרָא דִי יְקָרְבוּן קֳדָם יְיָ בֶּאֱנָשָׁא וּבִבְעִירָא יְהֵי לָךְ בְּרַם מִפְרַק תִּפְרוֹק יָת בּוּכְרָא דֶאֱנָשָׁא וְיָת בּוּכְרָא דִבְעִירָא מְסַאֲבָא תִּפְרוֹק:
@79 וּפוּרְקָנֵיהּ מִבַּר יַרְחָא תִּפְרוֹק בְּפוּרְסָנֵיהּ כְּסַף חַמְשָׁא סִלְעִין בְּסִלְעֵי קוּדְשָׁא עַשְׂרִין מָעִין הוּא:
@80 בְּרַם בּוּכְרָא דְתוֹרָא אוֹ בּוּכְרָא דְאִמְרָא אוֹ בּוּכְרָא דְעִזָא לָא תִפְרוֹק קוּדְשָׁא אִינוּן יָת דִמְהוֹן תִּזְרוֹק עַל מַדְבְּחָא וְיָת תַּרְבְּהוֹן תַּסֵיק קוּרְבַּן לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ:
@81 וּבִשְׂרְהוֹן יְהֵי לָךְ כְּחַדְיָא דַאֲרָמוּתָא וּכְשַׁקָא דְיַמִינָא דִילָךְ יְהֵי:
@82 כָּל אַפְרָשׁוּת קוּדְשַׁיָא דִי יִפְרְשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ יְהָבִית לָךְ וְלִבְנָיךְ וְלִבְנָתָיךְ עִמָךְ לִקְיַם עֲלָם קְיַים מְלַח עֲלָם הִיא קֳדָם יְיָ לָךְ וְלִבְנָךְ עִמָךְ:
@83 וַאֲמַר יְיָ לְאַהֲרֹן בְּאַרְעֲהוֹן לָא תַחֲסִין וְחוּלַק לָא יְהֵי לָךְ בֵּינֵיהוֹן מַתְּנָן דִי יְהָבִית לָךְ אִנוּן חוּלְקָךְ וְאַחֲסַנְתָּךְ בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@84 וְלִבְנֵי לֵוִי הָא יְהָבִית כָּל מַעַשְׂרָא בְּיִשְׂרָאֵל לְאַחֲסָנָא חֲלַף פּוּלְחַנְהוֹן דִי אִינוּן פָּלְחִין יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@85 וְלָא יִקְרְבוּן עוֹד בְּנֵי יִשְׂרָאֵל לְמַשְׁכַּן זִמְנָא לְקַבָּלָא חוֹבָא לִמְמָת:
@86 וְיִפְלְחוּן לֵוָאֵי אִינוּן יָת פּוּלְחַן מַשְׁכַּן זִמְנָא וְאִינוּן יְקַבְּלוּן חוֹבֵיהוֹן קְיַם עֲלָם לְדָרֵיכוֹן וּבְגוֹ בְּנֵי יִשְׂרָאֵל לָא יַחְסְנוּן אַחְסָנָא:
@87 אֲרֵי יָת מַעַשְׂרָא דִבְנֵי יִשְׂרָאֵל דִי יִפְרְשׁוּן קֳדָם יְיָ אַפְרָשׁוּתָא יְהָבִית לְלֵוָאֵי לְאַחֲסָנָא עַל כֵּן אֲמָרִית לְהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל לָא יַחְסְנוּן אַחֲסָנָא:
@88 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@89 וּלְלֵוָאֵי תְּמַלֵיל וְתֵימַר לְהוֹן אֲרֵי תִסְבוּן מִן בְּנֵי יִשְׂרָאֵל יָת מַעַשְׂרָא דִי יְהָבִית לְכוֹן מִנְהוֹן בְּאַחֲסַנְתְּכוֹן וְתַפְרְשׁוּן מִנֵיהּ אַפְרָשׁוּתָא קֳדָם יְיָ מַעַשְׂרָא מִן מַעַשְׂרָא:
@90 וְתִתְחַשֵׁב לְכוֹן אַפְרָשׁוּתְכוֹן כְּעִבּוּרָא מִן אִדְרָא וְכִמְלֵאָתָא מִן מַעְצַרְתָּא:
@91 כֵּן תַּפְרְשׁוּן אַף אַתּוּן אַפְרָשׁוּתָא קֳדָם יְיָ מִכֹּל מַעַשְׂרָתֵיכוֹן דִי תִסְבוּן מִן בְּנֵי יִשְׂרָאֵל וְתִתְּנוּן מִנֵיהּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ לְאַהֲרֹן כַּהֲנָא:
@92 מִכֹּל מַתְּנָתֵכוֹן תִּפְרְשׁוּן יָת כָּל אַפְרָשׁוּתָא דַיְיָ מִכָּל שׁוּפְרֵיהּ יָת מַקְדְשֵׁיהּ מִנֵיהּ:
@93 וְתֵימַר לְהוֹן בְּאַפְרָשׁוּתְכוֹן יָת שׁוּפְרֵיהּ מִנֵיהּ וְיִתְחַשֵׁב לְלֵּוָאֵי כַּעֲלָלַת אִדְרָא וְכַעֲלָלַת מַעֲצַרְתָּא:
@94 וְתֵיכְלוּן יָתֵיהּ בְּכָל אֲתַר אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן אֲרֵי אַגְרָא הוּא לְכוֹן חֲלַף פָּלְחַנְכוֹן בְּמַשְׁכַּן זִמְנָא:
@95 וְלָא תְקַבְּלוּן עֲלוֹהִי חוֹבָא בְּאַפְרָשׁוּתְכוֹן יָת שׁוּפְרֵיהּ מִנֵיהּ וְיָת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל לָא תְחַלְלוּן וְלָא תְמוּתוּן: פפפ:

@1 **ויקח קרח.** פרשה זו יפה נדרשת במדרש רבי תנחומא: **ויקח קרח.** לקח את עצמו לצד אחד להיות נחלק מתוך העדה לעורר על הכהנה, וזהו שתרגם אנקלוס ואתפלג נחלק משאר העדה להחזיק במחלוקת, וכן (איוב טו, יב) מה יקחך לבך, לוקח אתך להפליגך משאר בני אדם. דבר אחר ויקח קרח משך ראשי סנהדראות שבהם בדברים, כמו שנאמר (במדבר כ, כה) קח את אהרן, (הושע יד, ג) קחו עמכם דברים: **בן יצהר בן קהת בן לוי.** ולא הזכיר בן יעקב, שבקש רחמים על עצמו שלא יזכר שמו על מחלקתם, שנאמר (בראשית מט, ו) בקהלם אל תחד כבדי. והיכן נזכר שמו על קרח, בהתיחסם על הדוכן בדברי הימים, שנאמר (ד''ה א' ו, כב. כג) בן אביאסף בן קרח בן יצהר בן קהת בן לוי בן ישראל: **ודתן ואבירם.** בשביל שהיה שבט ראובן שרוי בחניתם תימנה, שכן לקהת ובניו החונים תימנה, נשתתפו עם קרח במחלקתו, אוי לרשע אוי לשכנו. ומה ראה קרח לחלוק עם משה, נתקנא על נשיאותו של אליצפן בן עזיאל שמנהו משה נשיא על בני קהת על פי הדבור. אמר קרח, אחי אבא ארבעה היו, שנאמר (שמות ו, יח) ובני קהת וגו' . עמרם הבכור נטלו שני בניו גדלה, אחד מלך ואחד כהן גדול, מי ראוי לטול את השניה, לא אני שאני בן יצהר שהוא שני לעמרם, והוא מנה נשיא את בן אחיו הקטן מכלם, הריני חולק עליו ומבטל את דבריו. מה עשה, עמד וכנס מאתים חמשים ראשי סנהדראות, רבן משבט ראובן שכניו, והם אליצור בן שדיאור וחבריו וכיוצא בו, שנאמר נשיאי עדה קראי מועד, ולהלן הוא אומר (במדבר א, טז) אלה קרואי העדה, והלבישן טליתות שכלן תכלת. באו ועמדו לפני משה. אמרו לו טלית שכלה של תכלת חיבת בציצית או פטורה. אמר להם חיבת. התחילו לשחק עליו, אפשר טלית של מין אחר חוט אחד של תכלת פוטרה, זו שכלה תכלת לא תפטור את עצמה: **בני ראובן.** דתן ואבירם ואון בן פלת:
@3 **רב לכם.** הרבה יותר מדאי לקחתם לעצמכם גדלה: **כלם קדשים.** כלם שמעו דברים בסיני מפי הגבורה: **ומדוע תתנשאו.** אם לקחת אתה מלכות לא היה לך לברר לאחיך כהנה, לא אתם לבדכם שמעתם בסיני אנכי ה' אלהיך (שמות כ, ב) , כל העדה שמעו:
@4 **ויפל על פניו.** מפני המחלקת, שכבר זה בידם סרחון רביעי, חטאו בעגל (שמות לב, יא) ויחל משה, במתאוננים (במדבר יא, יב) ויתפלל משה, במרגלים (שם יד, יג) ויאמר משה אל ה' ושמעו מצרים, במחלקתו של קרח נתרשלו ידיו. משל לבן מלך שסרח על אביו ופייס עליו אוהבו פעם ושתים ושלש, כשסרח רביעית נתרשלו ידי האוהב ההוא. אמר עד מתי אטריח על המלך, שמא לא יקבל עוד ממני:
@5 **בקר וידע** וגו' **.** עתה עת שכרות הוא לנו ולא נכון להראות לפניו והוא היה מתכון לדחותם שמא יחזרו בהם: **בקר וידע ה' את אשר לו.** לעבודת לויה: **ואת הקדוש.** לכהנה: **והקריב.** אותם אליו. והתרגום מוכיח כן ויקריב לקדמוהי יקריב לשמושיה. ומדרשו בקר, אמר לו משה, גבולות חלק הקדוש ברוך הוא בעולמו, יכולים אתם להפוך בקר לערב, כן תוכלו לבטל את זו, שנאמר (בראשית א, ה. ז) ויהי ערב ויהי בקר ויבדל, כך (דה''א כג, יג) ויבדל אהרן להקדישו וגו' :
@6 **זאת עשו קחו לכם מחתות.** מה ראה לומר להם כך, אמר להם בדרכי הגוים יש נמוסים הרבה וכומרים הרבה ואין כלם מתקבצים בבית אחד, אנו אין לנו אלא ה' אחד, ארון אחד ותורה אחת ומזבח אחד וכהן גדול אחד ואתם מאתים וחמשים איש מבקשים כהנה גדולה, אף אני רוצה בכך, הא לכם תשמיש חביב מכל, היא הקטרת החביבה מכל הקרבנות וסם המות נתון בתוכו שבו נשרפו נדב ואביהוא, לפיכך התרה בהם והיה האיש אשר יבחר ה' הוא הקדוש, כבר הוא בקדשתו. וכי אין אנו יודעים שמי שיבחר הוא הקדוש, אלא אמר להם משה הריני אומר לכם שלא תתחיבו, מי שיבחר בו יצא חי, וכלכם אובדים: **מחתות.** כלים שחותין בהם גחלים ויש להם בית יד:
@7 **רב לכם בני לוי.** דבר גדול אמרתי לכם. ולא טפשים היו שכך התרה בהם וקבלו עליהם לקרב, אלא הם חטאו על נפשותם, שנאמר את מחתות החטאים האלה בנפשתם. וקרח שפקח היה מה ראה לשטות זה, עינו הטעתו, ראה שלשלת גדולה יוצאה ממנו, שמואל ששקול כנגד משה ואהרן. אמר בשבילו אני נמלט, ועשרים וארבע משמרות עומדות לבני בניו כלם מתנבאים ברוח הקדש, שנאמר (ד''ה א' כה, ה) כל אלה בנים להימן, אמר אפשר כל הגדלה הזאת עתידה לעמוד ממני ואני אדום, לכך נשתתף לבוא לאותה חזקה, ששמע מפי משה שכלם אובדים ואחד נמלט. אשר יבחר ה' הוא הקדוש, טעה ותלה בעצמו, ולא ראה יפה, לפי שבניו עשו תשובה, ומשה היה רואה. תנחומא: **רב לכם.** דבר גדול נטלתם בעצמכם לחלוק על הקדוש ברוך הוא:
@8 **ויאמר משה אל קרח שמעו נא בני לוי.** התחיל לדבר עמו דברים רכים, כיון שראהו קשה ערף, אמר עד שלא ישתתפו שאר השבטים ויאבדו עמו, אדבר גם אל כלם, התחיל לזרז בהם שמעו נא בני לוי:
@9 **ולעמד לפני העדה.** לשיר על הדוכן:
@10 **ויקרב אתך.** לאותו שרות שהרחיק ממנו שאר עדת ישראל:
@11 **לכן.** בשביל כך אתה וכל עדתך הנעדים אתך על ה' כי בשליחותו עשיתי לתת כהנה לאהרן ולא לנו היא המחלוקת הזו:
@12 **וישלח משה** וגו' **.** מכאן שאין מחזיקין במחלוקת, שהיה משה מחזר אחריהם להשלימם בדברי שלום: **לא נעלה.** פיהם הכשילם, שאין להם אלא ירידה:
@14 **ותתן לנו.** הדבר מוסב על לא האמור למעלה, כלומר לא הביאותנו ולא נתת לנו נחלת שדה וכרם, אמרת לנו (שמות ג, יז) אעלה אתכם מעני מצרים אל ארץ וגו' , משם הוצאתנו ולא אל ארץ זבת חלב ודבש הביאתנו, אלא גזרת עלינו להמיתנו במדבר, שאמרת לנו (במדבר יד, כט) במדבר הזה יפלו פגריכם: **העיני האנשים ההם תנקר** וגו' **.** אפלו אתה שולח לנקר את עינינו אם לא נעלה אליך, לא נעלה: **האנשים ההם.** כאדם התולה קללתו בחברו:
@15 **ויחר למשה מאד.** נצטער עד למאד: **אל תפן אל מנחתם.** לפי פשוטו הקטרת שהם מקריבים לפניך מחר אל תפן אליהם. והמדרש אומר יודע אני שיש להם חלק בתמידי צבור, אף חלקם לא יקבל לפניך לרצון, תניחנו האש ולא תאכלנו: **לא חמור אחד מהם נשאתי.** לא חמורו של אחד מהם נטלתי. אפלו כשהלכתי ממדין למצרים והרכבתי את אשתי ואת בני על החמור, והיה לי לטול אותו החמור משלהם, לא נטלתי אלא משלי. ותרגום אנקלוס, שחרית, לשון ארמי, כך נקראת אנגריא של מלך שחוור:
@16 **והם.** עדתך:
@17 **והקרבתם** וגו' **איש מחתתו.** החמשים ומאתים איש שבכם:
@19 **ויקהל עליהם קרח.** בדברי ליצנות. כל הלילה ההוא הלך אצל השבטים ופתה אותם כסבורין אתם שעלי לבדי אני מקפיד, איני מקפיד אלא בשביל כלכם. אלו באין ונוטלין כל הגדלות, לו המלכות ולאחיו הכהנה, עד שנתפתו כלם: **וירא כבוד ה'.** בא בעמוד ענן:
@22 **אל אלהי הרוחת.** יודע מחשבות. אין מדתך כמדת בשר ודם, מלך בשר ודם שסרחה עליו מקצת מדינה אינו יודע מי החוטא, לפיכך כשהוא כועס נפרע מכלם, אבל אתה לפניך גלויות כל המחשבות ויודע אתה מי החוטא: **האיש אחד.** הוא החוטא ואתה על כל העדה תקצוף. אמר הקדוש ברוך הוא יפה אמרת, אני יודע ומודיע מי חטא ומי לא חטא:
@24 **העלו** וגו' **.** כתרגומו הסתלקו מסביבות משכן קרח:
@25 **ויקם משה.** כסבור שישאו לו פנים ולא עשו:
@27 **יצאו נצבים.** בקומה זקופה לחרף ולגדף, כמו (שמואל א' יז, טז) ויתיצב ארבעים יום דגלית: **ונשיהם ובניהם וטפם.** בא וראה כמה קשה המחלוקת, שהרי בית דין של מטה אין עונשין אלא עד שיביא שתי שערות, ובית דין של מעלה עד עשרים שנה, וכאן אבדו אף יונקי שדים:
@28 **לעשות את כל המעשים האלה.** שעשיתי על פי הדבור לתת לאהרן כהנה גדולה ובניו סגני כהנה ואליצפן נשיא הקהתי:
@29 **לא ה' שלחני.** אלא אני עשיתי הכל מדעתי ובדין הוא חולק עלי:
@30 **ואם בריאה.** חדשה: **יברא ה'.** להמית אותם במיתה שלא מת בה אדם עד הנה, ומה היא הבריאה, ופצתה האדמה את פיה ותבלעם, אז וידעתם כי נאצו הם את ה', ואני מפי הגבורה אמרתי. ורבותינו פרשו אם בריאה. פה לארץ מששת ימי בראשית מוטב, ואם לאו יברא ה':
@34 **נסו לקולם.** בשביל הקול היוצא על בליעתן:
@37 **ואת האש.** שבתוך המחתות: **זרה הלאה.** לארץ מעל המחתות: **כי קדשו.** המחתות ואסורין בהנאה, שהרי עשאום כלי שרת:
@38 **החטאים האלה בנפשתם.** שנעשו פושעים בנפשתם, שנחלקו על הקדוש ברוך הוא: **רקעי.** רדידין: **פחים.** טסין מרדדין טינבי''ש בלע''ז : **צפוי למזבח.** למזבח הנחשת: **ויהיו לאות.** לזכרון, שיאמרו אלו היו מאותן שנחלקו על הכהנה ונשרפו:
@39 **וירקעום.** אטינבירנ ''ט בלע ''ז:
@40 **ולא יהיה כקרח.** כדי שלא יהיה כקרח: **כאשר דבר ה' ביד משה לו.** כמו עליו, על אהרן דבר אל משה, שיהיה הוא ובניו כהנים, לפיכך לא יקרב איש זר אשר לא מזרע אהרן וגו' , וכן כל לי ולו ולהם הסמוכים אצל דבור פתרונם כמו על. ומדרשו על קרח. ומהו ביד משה ולא כתב אל משה, רמז לחולקים על הכהנה שלוקין בצרעת, כמו שלקה משה בידו שנאמר (שמות ד, ו) ויוציאה והנה ידו מצרעת כשלג, ועל כן לקה עזיה בצרעת:
@46 **וכפר עליהם.** רז זה מסר לו מלאך המות כשעלה לרקיע, שהקטרת עוצר המגפה כדאיתא במסכת שבת (שבת פט א) :
@48 **ויעמד בין המתים** וגו' **.** אחז את המלאך והעמידו על כרחו. אמר לו המלאך הנח לי לעשות שליחותי. אמר לו משה צוני לעכב על ידך. אמר לו אני שלוחו של מקום ואתה שלוחו של משה. אמר לו אין משה אומר כלום מלבו אלא מפי הגבורה, אם אין אתה מאמין הרי הקדוש ברוך הוא ומשה אל פתח אהל מועד בא עמי ושאל. וזהו שנאמר וישב אהרן אל משה. דבר אחר למה בקטרת, לפי שהיו ישראל מליזין ומרננים אחר הקטרת לומר סם המות הוא, על ידו מתו נדב ואביהוא, על ידו נשרפו חמשים ומאתים איש, אמר הקדוש ברוך הוא תראו שעוצר מגפה הוא, והחטא הוא הממית:
@53 **כי מטה אחד.** אף על פי שחלקתים לשתי משפחות משפחת כהנה לבד ולויה לבד מכל מקום שבט אחד הוא:
@55 **והשכתי.** כמו וישכו המים (בראשית ח, א) , וחמת המלך שככה: (אסתר ז, י) כא **בתוך מטותם.** הניחו באמצע, שלא יאמרו מפני שהניחו בצד שכינה פרח:
@58 **ויצא פרח.** כמשמעו: **ציץ.** הוא חנטת הפרי כשהפרח נופל: **ויגמל שקדים.** כשהכר הפרי הכר שהן שקדים, לשון (בראשית כא, ח) ויגדל הילד ויגמל, ולשון זה מצוי בפרי האילן, כמו (ישעיה יח, ה) ובסר גמל יהיה נצה. ולמה שקדים, הוא הפרי הממהר להפריח מכל הפרות, אף המעורר על הכהנה פרענותו ממהרת לבא, כמו שמצינו בעזיה (ד''ה ב' כו, יט) והצרעת זרחה במצחו. ותרגומו וכפית שגדין, כמין אשכול שקדים יחד כפותים זה על זה:
@60 **למשמרת לאות.** לזכרון שבחרתי באהרן הכהן ולא ילונו עוד על הכהנה: **ותכל תלונתם.** כמו ותכלה תלונתם, לשון שם מפעל יחיד לנקבה כמו תלנתם מורמורי''ץ בלע''ז [תלנות] ויש חלוק בין תלנותם לתלנתם, תלנתם תלנה אחת, תלנותם שם דבר בלשון יחיד, ואפלו הם תלנות הרבה:
@63 **כל הקרב הקרב** וגו' **.** אין אנו יכולין להיות זהירין בכך, כלנו רשאין להכנס לחצר אהל מועד ואחד שיקריב עצמו יותר מחברו ויכנס לתוך אהל מועד ימות: **האם תמנו לגוע.** שמא הפקרנו למיתה:
@64 **ויאמר ה' אל אהרן.** למשה אמר שיאמר לאהרן להזהירו על תקנת ישראל שלא יכנסו למקדש: **אתה ובניך ובית אביך.** הם בני קהת אבי עמרם: **תשאו את עון המקדש.** עליכם אני מטיל ענש הזרים שיחטאו בעסקי הדברים המקדשים המסורים לכם הוא האהל והארון והשלחן וכלי הקדש אתם תשבו ותזהירו על כל זר הבא לגע: **ואתה ובניך.** הכהנים: **תשאו את עון כהנתכם.** שאינה מסורה ללוים ותזהירו הלוים השוגגים שלא יגעו אליכם בעבודתכם:
@65 **וגם את אחיך.** בני גרשון ובני מררי: **וילוו.** ויתחברו אליכם להזהיר גם את הזרים מלקרב אליהם: **וישרתוך.** בשמירת השערים ולמנות מהם גזברין ואמרכלין:
@67 **וזר לא יקרב אליכם.** אתכם אני מזהיר על כך:
@68 **ולא יהיה עוד קצף.** כמו שהיה כבר, שנאמר (במדבר יז, יא) כי יצא הקצף:
@69 **לכם מתנה נתנים.** יכול לעבודתכם של הדיוט, תלמוד לומר לה', כמו שמפורש למעלה, לשמור משמרת גזברין ואמרכלין:
@70 **עבדת מתנה.** במתנה נתתיה לכם:
@71 **ואני הנה נתתי לך.** בשמחה. לשון שמחה הוא זה, כמו (שמות ד, יד) הנה הוא יוצא לקראתך וראך ושמח בלבו, משל למלך שנתן שדה לאוהבו ולא כתב ולא חתם ולא העלה בערכאין. בא אחד וערער על השדה. אמר לו המלך כל מי שירצה יבא ויערער לנגדך, הריני כותב וחותם לך ומעלה בערכאין, אף כאן לפי שבא קרח וערער כנגד אהרן על הכהנה, בא הכתוב ונתן לו עשרים וארבע מתנות כהנה בברית מלח עולם, ולכך נסמכה פרשה זו לכאן: **משמרת תרומתי.** שאתה צריך לשמרן בטהרה: **למשחה.** לגדלה:
@72 **מן האש.** לאחר הקטרת האשים: **כל קרבנם.** כגון זבחי שלמי צבור: **מנחתם חטאתם ואשמם.** כמשמעו: **אשר ישיבו לי.** זה גזל הגר:
@73 **בקדש הקדשים תאכלנו** וגו' **.** למד על קדשי קדשים שאין נאכלין אלא בעזרה ולזכרי כהנה:
@74 **תרומת מתנם.** המורם מן התודה ומהשלמים ואיל נזיר: **לכל תנופת.** שהרי אלו טעונין תנופה: **כל טהור.** ולא טמאים. דבר אחר כל טהור לרבות אשתו:
@75 **ראשיתם.** היא תרומה גדולה:
@81 **כחזה התנופה וכשוק הימין.** של שלמים שנאכלים לכהנים לנשיהם ולבניהם ולעבדיהם לשני ימים ולילה אחד, אף הבכור נאכל לשני ימים ולילה אחד: **לך יהיה.** בא רבי עקיבא ולמד הוסיף לך הכתוב הויה אחרת, שלא תאמר כחזה ושוק של תודה, שאינו נאכל אלא ליום ולילה:
@82 **כל תרומת הקדשים.** מחבתה של פרשה זו כללה בתחלה וכללה בסוף ופרט באמצע: **ברית מלח עולם.** כרת ברית עם אהרן בדבר הבריא ומתקיים ומבריא את אחרים: **ברית מלח.** כברית הכרותה למלח שאינו מסריח לעולם:
@83 **וחלק לא יהיה לך בתוכם.** אף בבזה:
@86 **והם.** הלוים ישאו עונם של ישראל, שעליהם להזהיר הזרים מגשת אליהם:
@87 **אשר ירימו לה' תרומה.** הכתוב קראו תרומה עד שיפריש ממנו תרומת מעשר:
@90 **ונחשב לכם תרומתכם כדגן מן הגרן.** תרומת מעשר שלכם אסורה לזרים ולטמאים וחייבין עליה מיתה וחמש כתרומה גדולה שנקראת ראשית דגן מן הגרן: **וכמלאה מן היקב.** כתרומת תירוש ויצהר הנטלת מן היקבים: **מלאה.** לשון בשול תבואה שנתמלאת: **יקב.** הוא הבור שלפני הגת שהיין יורד לתוכו. וכל לשון יקב חפירת קרקע הוא, וכן (זכריה יד, י) יקבי המלך, הוא ים אוקיינוס חפירה שחפר מלכו של עולם:
@91 **כן תרימו גם אתם.** כמו שישראל מרימים מגרנם ומיקביהם תרימו גם אתם ממעשר שלכם, כי הוא נחלתכם:
@92 **מכל מתנתיכם תרימו את כל תרומת ה'.** בתרומה גדולה הכתוב מדבר, שאם הקדים לוי את הכהן בכרי וקבל מעשרותיו קודם שיטול כהן תרומה גדולה מן הכרי, צריך להפריש הלוי מן המעשר תחלה אחד מחמשים לתרומה גדולה, ויחזור ויפריש תרומת מעשר:
@93 **בהרימכם את חלבו ממנו.** לאחר שתרימו תרומת מעשר ממנו: **ונחשב.** המותר ללוים חלין גמורין: **כתבואת גרן.** לישראל, שלא תאמר הואיל וקראו הכתוב תרומה שנאמר כי את מעשר בני ישראל אשר ירימו לה' תרומה, יכול יהא כלו אסור, תלמוד לומר ונחשב ללוים כתבואת גרן, מה של ישראל חלין, אף של לוי חלין:
@94 **בכל מקום.** אפלו בבית הקברות:
@95 **ולא תשאו עליו חטא** וגו' **.** הא אם לא תרימו תשאו חטא: **ולא תמותו.** הא אם תחללו תמותו:
@96 **ויאמר שמואל וגו' ונחדש שם המלוכה.** לפי שבראשונה היו עוררים על הדבר, ועתה נתרצו כולם:
@99 **ואני זקנתי ושבתי.** אמרו רבותינו: זקנה קפצה עליו, כדאיתא במסכת תענית ( ה ב ):
@100 **את שור מי לקחתי.** לעבודתי: **וחמור מי לקחתי.** כשהייתי הולך מעיר לעיר לשפוט אותם על עסקי צרכיהם, הייתי הולך על החמור שלי, והיה לי ליטול משלהם: **את מי רצותי.** כל לשון מרוצה הסמוך לעושק, לשון עשוק ורצוץ הוא, חומס דלים ורוצץ: **ואעלים עיני בו.** כדי להעלים עיני מן המשפט בשביל הממון: **ואשיב לכם.** כל מה שתאמרו:
@102 **ויאמר עד.** בת קול יוצאת ואומרת: 'עד', וזה אחד משלשה מקומות שהופיעה רוח הקודש בבית דין של מטה, כדאיתא במסכת מכות ( כג ב ):
@103 **אשר עשה את משה ואת אהרן.** להיות נכונים לשליחותו, להוציא אבותיכם ממצרים:
@104 **ואשפטה אתכם.** אתוכח עמכם:
@108 **ירובעל.** זה גדעון: **בדן.** זה שמשון, שמשבט דן בא: **ואת יפתח.** הרי שלשה קלי עולם, עם שלשה חמורי עולם, משה ואהרן ושמואל, לומר לך, הקל בדורו, כחמור בדורו, כל בית דין המתמנה על הדור, צריך לילך אחריו כאלו הוא אביר שבאבירים:
@111 **והיתם גם אתם.** ותתקיימו לאורך ימים גם אתם גם המלך:
@112 **והיתה יד ה' בכם ובאבותיכם.** כלומר והיתה בכם אחר שהיתה באבותיכם. ורבותינו אמרו ( יבמות סג ב ): בכם ובאבותיכם, חטוטי שכבי, והיא מכת בזיון על המתים:
@113 **התיצבו וראו וגו'.** וכשם שעל ידי תפלתי אני יכול לשנות את העתים, כך אם פגעה בכם מלחמה, היה כח בתפלתי לעמוד על האויב, ולא הייתם צריכים לשאול מלך בחיי, ואף על פי שאני זקן:
@114 **הלא קציר חטים היום.** והגשמים סימן קללה, וקשה בעיני הקב"ה להביא פורענות חנם, אף על פי כן יש בי כח, ואקרא אל ה' ויתן קולות ומטר: **ודעו וראו.** כי לא הייתם צריכים לשאול מלך לזלזל בי:
@119 **בעבור שמו הגדול.** אשר יצא שמו עליכם שהוא מושיעכם, ולמען לא יתמעט שם גדלו: **הואיל ה'.** נשבע, כמו ( לקמן יד כה ): ויואל שאול את העם:

@1 **ויקח קרח.** הרצון בו עניין לקיחת הנפשות באופן שימשך לב רבים מישראל אליו לקנאתו על גדולת משה ואהרן והנה לא ספרה התורה הפתויים אשר פתה בהן לב החמשים ומאתים איש אשר היו מגדולי העם ומהנכבדים שבהם וכבר זכרו מזה רז"ל קצת ספורים במדרשיהן והוא מבואר שכבר משכו לבם כשאמרו שכל הגדולה נטל משה לעצמו ולאחיו אהרן כי הוא יה מלך ואהרן כהן גדול והיתה הכהונ' לו ולזרעו אחריו ולא עבר זר בתוכם וידמה מזה הספור שלא היו מרעמים על מלכות משה רק על כהונת אהרן ולזה אמר ובקשתם גם כהונה:
@5 **בקר ויודע יי' את אשר לו.** ר"ל שהגדולה הזאת לא נתתי לאהרן מעצמי רק ה' יתע' בחרו וזה יתבאר בבקר היום הבא אחר זה והנה הודיעם בזה המאמר כי ה' יתע' לא יבחר כי אם באחד לבד ולזה היה לירא מהקריב הקטרת כי לא יבחר בכלן רק באחד לבד:
@7 **ותנו בהן אש ושימו בהם קטרת.** אחשוב שהאש לקחו מהמזבח הנחשת שאם היה שם אש זרה לא יהיה שם אות מפני מיתתם שאינן ראויים לכהונה כי גם בני אהרן עם היותם כהנים מתו בהקריבם אש זרה לפני יי' ולזאת הסבה בעינה אחשוב גם כן שלקחו מהקטרת שהיו מקטירים ממנה במזבח הפנימי לא קטרת זרה שאם היו מקטירים שם קטרת זרה לא תהיה מיתתם על זה מורה שלא בחר השם ית' בהם להיותם כהני' כי אפילו זרע אהרן היו מתים אם היו עושים כן:
@7 **רב לכם בני לוי.** אמר זה להצילם שלא יבקשו גדולות כי די להם במה שנתן השם ית' מהגדולה כי הוא היה חומל עליהם אף על פי שהיו מעצבים אותו וכאשר ראה שלא נתפייסו בזה אך היו מחזיקין בבקשתם אמ' להן מש שמעו נא בני לוי המעט מכם מה שנתן לכם הש' ית' מהגדולה שהבדיל אתכם מעדת ישראל להקריב אתכם אליו יתע' יותר משאר העם וששם אתכם עובדים עבודת משכן השם ית' באופן שקדם בראש זה הספר רוצה לומר לעבוד ולמשא ולשמור משמרת המשכן והבדיל אתכם לעמוד לפני העדה לשרתם ידמה שזה השרות הוא השיר שהיו הלוים אומרים בפה כמו שנתבאר בעזרא ולמדנו מזה שהשרו' הוא בעמידה עם שזה דבר מבואר בעצמו כי הישיבה מורה אדונות ושררה לא שירות ויקרב אותך ואת כל אחיך בני לוי אתך. שהם ממשפחת קהת יותר משאר משפחות הלויים בששם עבודתכם בקדש הקדשים ולא די לכם זה אלא שאתם מבקשים עוד כהנה ואחר שכן הוא שזה העניין היה כלו מה' יתע' הנה אתה וכל עדתך נועדים לעשות כנגד השם יתעלה לא כנגד אהרן כי לא היה זה מצדו אך השם ית' בחר אותו להיות לו לכהן:
@14 **ותתן לנו נחלת שדה וכרם.** רוצה לומר שלא די שלא הביאותנו אל ארץ זבת חלב ודבש כמו שיעדת לנו אפילו שדה וכרם לא נתת לנו ועם זה התחשוב לעשותנו כעורים שלא נראה כי הבטחתנו בדברי שקר:
@15 **אל תפן אל מנחתם.** אחשוב שאין זה בקשה ממשה כי זה בלי ספק לא היה צריך לזאת הבקשה כי הם היו עושים כנגד ה' ית' ואין ספק שהוא לא יפנה אל מנחתם ולזה ידמה שיהיה עניינו כמו זכור מלחמה אל תוסף שאינו בקשה אך הוא ספור העניין וכזה אמר משה הנה אין ספק שאתה אל תפן אל מנחתם כי לא עשיתי להם שום דבר שיהיה להם בעבורו מקום להתרעם על שררותי:
@19 **ויקהל עליהם קרח את כל העדה את פתח אהל מועד.** ידמה שמשך קרח בדבריו החמשים ומאתים איש לעשות זה כי אולי הם יראים ממה שאמר מזה שאשר יבחר בו השם ית' הוא הקדוש כי זה מורה שכלם ימותו זולת אחד מהם או יהיה אמרו כל העדה שב אל ישראל כשהיה מושך את לבבם להתרעם על משה על דבר זאת השררה:
@22 **אל אלהי הרחו' לכל בשר.** הרצון אמרו לכל בשר לכל אישי האדם כטעם אמרו יבא כל בשר להשתחות לפני והנה הרצון בזה אל שהוא שופט הרוחות אשר לכל בשר בשיודע לאיש ואיש מהם צדקו ורשעתו היהיה נכון שתקצוף על העדה בעבור חטא איש אחד חלילה לך מעשו' זאת:
@28 **בזאת תדעון כי השם שלחני וגו'.** נתן להם משה אות אשר יכירו בו כי זה פעל אלהי והוא שאלו לא ימותו כמות כל האנשים אך שהשם יתעלה יברא בריאה בעבורן תתחדש ממנה פתיחת הארץ את פיה ותבלע אותם ואת כל אשר להם באופן שירדו חיים בעומק הארץ והוא שקרא שאול והנה היתה זאת הבריאה בהשם יתעלה אז על דרך מופת בבטן הארץ אשר תחתיהם מה שנה חדש ממנו בקיעת הארץ והנה היה ענין זה המופת שמה שיעשה על דרך הטבע בזמן ארוך אורך נפלא עשה השם יתעלה על דרך המופת בזמן רגע וכן דרך שאר המופתים הנעשים על ידי נביא כמו שביארנו בששי מספר מ"י וכן אמרו זה רז"ל אם נברא פה לגהנם מוטב ואם לא יברא יי' ובסוף הענין אמרו שהמופת היה לקרובי פתחא אול יספק מספק ויאמ' כי עדיין היה אפשר שיהרהרו שמא היה משה יודע על דרך הנבואה כי המקום ההוא שהיה בו הגיע עתו להבקע שם הארץ ולא יהיה מזה אם כן מופת על שזה הענש הגיע להם מפני מרדם אלא שהיתר זה הספק הוא ממה שיקל וזה כי לא יתכן שיאמר שזה היה במקרה ויסכים זה למקום שהיו בו אלו האנשים לבד כי מה שבמקרה בזה האופן הוא מעטי אבל שיסכי' לרבוי מה ויבחרם מבין השאר הנה זה בלתי אפשר שיוחס אל המקרה עם שכבר נגלה להם שימותו האנשים החמשים ומאתים איש מקריבי הקטרת וזה ממה שיורה שכל זה היה להם על צד העונש מהש"י כי החוטאים לבד מתו לא זולתם והיותר נפלא מכל זה שבמקום בעינו שנבקע הארץ עשה השם יתע' שהשאיר ממנה המקום שהיו בני קרח כי הם לא מתו כמו שיבא בפרשת פינחס והנה היה זה כן מפני שלא היו נמשכים עצת אביהם והנה אמרו רבותינו ז"ל שמקום נתבצר להם בגהנם והנה מה שאמר ואת כל האדם אשר לקרח. רוצה לומר בני ביתו הנמשכים לעצתו:
@37 **ואת האש זרה הלאה כי קדש.** ידמה מזה המקום שכלי שרת מתקדשי' אפילו בזולת משיחה כשישימו בהם מה שהם משמשים בו תדע שאלו הכלם קדשו כי הקריבום לפני השם כששמו בהם הקטרת אך עבודתם לא קדשה אותם כי היא לא היתה עבודה והנה רצה הש' ית' שירקעום צפוי למזבח לפרסם זה העניין באופן שיירא מי שאינו מזרע אהרן להקטיר קטרת לפני יי' פן יקרה לו כמו מה שקרה לקרח ועדתו על עשותם כן:
@40 **כאשר דבר השם ביד משה.** רוצה לומר אל אלעזר כי השם ית' דבר לו ביד משה שיקח את המחתות ויעשה אותם רקועי פחים צפוי למזבח:
@46 **קח את המחתות ותן עליה אש מעל המזבח.** ר"ל מעל מזבח החיצון כי כן היה משפט בהקטרת הקטרת על מזבח הזהב שהיו לוקחים אש מעל מזבח החיצון כמו שהתבאר במה שקדם וזה לאות שזה הקטרת היה קטרת הסמים שהיו מקטירים על מזבח הזהב. ויעתר לו השם יתע'. עד שכבר נעצרה המגפה תכף שהקטיר הקטרת:
@52 **וקח מאתם מטה מטה לבית אב וגו'.** הנה עשה זה המופת הנפלא שהוציא מטה אהרן פרח וצץ ציץ וגמל שקדים בזמן קצר מאד כדי שיתפרסם לישראל כלם כי השם ית' בחר באהרן לבדו להיות לו לכהן השב את מטה אהרן לפני העדות למשמרת כן מצאנו גם כן בצנצנת המן ששמהו אהרן לפני העדות למשמרת ולפי שהארון נקרא ארון העדות מצד הלוחות שהיו בתוכו שהן עדות לעניין התורה ואמר לפני העדות ולא אמ' לפני הארון למדנו מזה שבתוך הארון היו שאם היו חוץ ממנה היה ראוי שיאמר לפני הארון ולא לפני העדות עם שכבר יתכן יותר שהוא למשמרת כשהיה תוך הארון:
@64 **אתה ובניך ובית אביך אתך תשאו את עון המקדש.** הרצון בזה שאין לירוא לישראל שימותו על דבר משכן ה' כמו שאמר כל הקרב אל משכן ה' ימות האם תמנו לנוע וזה כי אתה ובניך והם הכהנים ובית אביך אתך והם הלוים תשאו עליכם עון המקדש אם יקרב אחד מכם במקום שאין לו רשות להכנס כאלו תאמר אם יכנס כהן גדול לפני לפנים בזולת יום הכפורים או אם יבאו אל אהל מעד או אם יגשו אל המזבח הבלתי ראוים לזה וכן תעשו בלויים אם יקרבו במה שאין להם רשות בו מהמשכן אבל איש על עבודתו ועל משאו:
@64 **ואתה ובניך אתך תשאו את עון כהונתכם.** ר"ל מה שהיה מהשגגה בענין העבודות שיעשו הכהנים במקדש יהיה משא העון על אהרן ועל בניו:
@65 **וילוו עליך וישרתוך.** ר"ל בעניין הכהונה וזה השרות הוא בעניין השיר שהיו משוררים הלוים בשעה שהיו הכהנים עובדים עבודתם אלא שהלוים לא יהיו לפני אהל העדות לעבוד עבודת הכהנה אבל יהיו הכהנים מבפנים לפני אהל העדות והלוים מבחוץ ולמדנו גם כן מזה המאמר שאמר ואתה ובניך אתך לפני אהל העדות שהוא ראוי שישמרו הכהנים בית המקדש תמיד ובזאת השמירה ילוו עליהם הלויים כמו שאמר ושמרו את משמרתך ומשמרת כל האהל אבל יהיו בזאת השמירה הכהנים לפני אהל העדות והלוים מבחוץ וכבר למדנו שזה ההלוות שהלוו הלוים לכהנים הוא עניין העבודה בשיר מאשר אמר אך אל כל כלי הקדש ואל המזבח לא יקרבו והנה כלי הקדש הם החצוצרות שהכהני' היו תוקעים בהם בשעת העבודה. והמזבח היא העבודה הנעשית בענין הקרבנות ויתר הדברים הבאים באחת מהמזבחות ומאשר לא הוציאם כי אם מאלו הענינים למדנו שהם משתתפים להם בענין אינו בכל הקדש ואינו קרב למזבח וכבר נתפרסם עוד ענין שרות הלו' בשיר בספר עזרא:
@66 **ושמרו את משמרתך ומשמרת כל האהל.** הוא משמרת כל העבודה המיוחדת להן ומש שימנום עליהם הכהנים בשמירתם כשיעשו להן גזברים ואמר כלים לשמירת הדברים אשר בבית ומשמרת כל האהל כשיהיו מהם שוערים ביום לשמור הבית ובלילה שלא ישנו קצתם כדי שתשלם לו השמירה תמיד ולא ימותו גם הם גם אתם. ולמדנו מזה שהלוים שנכנסו בעבודת הכהנים חייבים מיתה ולזה אמר גם הם ואמר גם אתם להורות שאם לא הקריבו הכהנים אליהם הלוים לעבוד עבודתם המיוחדת להם אבל עבדו הכהנים אותם העבודות הנה הכהנים חייבים מיתה ומזה המקום למדנו שכל מי שנכנס בעבוד' חברו כאלו תאמר שעבדו בני קהת עבודת בני גרשון או הפך:
@67 **ונלוו עליך ושמרו וגו'.** אחשוב שהרצון בעבודת האהל פירוקו והקמתו ומשאו על האופן הקודם ר"ל שהכהנים היו משימין הלוים איש על עבודתם ועל משאם:
@67 **וזר לא יקרב אליכם.** זו אזהרה כוללת לכל העבודות המיוחסות לכהנים וכבר ביאר בסוף זאת הפרשה העונש והוא אמרו והזר הקרב יומת וזאת המיתה היא חנק לפי מה שהתבאר מהשרשים הכוללים:
@68 **ושמרו את משמרת הקדש ואת משמרת המזבח וגו'.** הוא האזהרה שלא להתעצל בשמירתן כדי שלא יקרה עון בעניני שמיר' המקדש ובעניני העבוד' שתעש' במזבח ובזה האופן יהיו ישראל נשמרים ממה שהיו יראי' באמרם כל הקרב הקרב אל משכן ה' ימות כי הכהנים והלוים ישמרום מלהכנס במקדש ובעבדה באופן הנזכר אחר זה:
@69 **ואני הנה לקחתי את אחיכם הלוים מתו בני ישראל.** ר"ל שרבתי אותם לי ובחרתי בהם לעבודתי ולזאת הסבה לא היה ללוי חלק ונחלה בתוך בני ישראל והיו נתונים להם המעשרות כדי שיחיו בהם בזולת עמל ויהיה להם פנאי בחכמה ובתורה לעבוד השם יתע':
@69 **לכם מתנה נותנים להשם.** אמר שהלוים הם מתנה לכהנים אך לא שיעבדו הלוים הכהנים אלא בדברים שהם לה' והם העבודות הנזכרות שהיו מיוחדין ללוים והיו הכהנים משימין אותן עליהם לעבודת אהן מועד:
@70 **ואתה ובניך אתך תשמרו את כהונתכם וגו'.** ר"ל שאהרן ובניו לבדם יתעסקו בעבודת הקרבנות והנלוה אליהם ובקטרת ובמה שהוא מבית לפרכת יתעסק בו אהרן לבדו אחת בשנה כמו שקדם:
@70 **עבדת מתנה אתן את כהנתכם.** א"ל שזאת העבודה הוא לכם מתנה ואין מנהגה כמנהג העבודות שיכבדו על העובד אבל הנני נותן לכם מתנה נפלאה כזאת הכהונה אם מצד עצמותם לפי מה שהתבאר מדברינו בענין הקרבנות אם מצד המתנות הנתנות לכם מישראל בסבת הכהונה כמו שזכרנו בסמוך:
@70 **והזר הקרב יומת.** מפני 'סמך זה המאמר לעניין העבודה למדנו שלא יתחייב זר מיתה כי אם על העבודה ודבר העבודה הוא מה שהוא מכוון בעצמותו כמו נתינת האש על המזבח ועריכת העצים ומה שידמה לזה ואולם מה שאינו מכוון בעצמותו כמו הרמת הדשן ומה שידמה לו לא יתחייב מיתה עליו הזר וכבר ביארו זה ז"ל ממה שאמר עבודת מתנה אמרו עבודת מתנה עבודת מתנה ולא עבודת סלוק:
@71 **וידבר השם אל אהרן.** ראוי שלא יעלם ממנו שזה המאמר היה למשה בעבור אהרן וכן העניין בכל מה שדומה לזה כי התורה בכללה נתנה לנו ע"פ משה מפי הגבורה:
@71 **ואני הנה נתתי לך את משמרת תרומותי.** בעבור שמצאנו בזה המקום לך נתתים למשחה ולבניך לחק עלם ובמה שכלל בזאת הפרשה מעניין אלו התרומות אמר נתתי לך ולבניך ולבנותיך אתך ידענו שאין הכונה לזכרי כהנה לבד ומה שזכר נתנו לזכרים ולנקבות ולפי שמצאנו שמה שהוא לזכרי כהנה לבד הוא קדש הקדשים ידענו כי בו העיד בזה הפסוק ולזה המשיך הספור אחריו בענין קדש הקדשים ולפי שהתרומה אשר בקדש הקדשים היו לשם יתע' והנותר הוא לכהנים ולא יזכו הכהנים בנותר אם לא זכה המזבח תחלה באלו התרומות אמר שכבר נתתי לך את משמר' תרומותי שתעשה מה מה שצויתי להקטיר על המזבח זה המורם:
@71 **לכל קדשי בני ישראל לך נתתים למשחה.** ר"ל הקדשים ההן שנשארו אחר התרומה לך יהיה לאכלה ולבניך כי לא יאכלו אותם כי אם זכרי כהנה או אפשר שנאמר שיכלול בזה המאמר גם כן חלק הכהנים מקדשים קלים כי הם לא יזכור בו גם כן כי אם אחר' שזכה המזבח במורם מהם להשם ואמר ולבניך לבד לפי שזה דבר כולל לכל חלק הכהנים מן הכהנים היו קדשים היו קדשי הקדשים או קדשים קלים ואין הענין כן בבנות כי לא יאכלו מקדשי הקדשים:
@71 **לך נתתים למשחה.** ר"ל לגדולה ולזה ראוי שלא יקל בהם לאכלם כמנהג מאכל הפחותים אבל ראוי שינהגו באכילתם בכבוד לכבוד השם יתעלה:
@71 **ולבניך לחק עולם.** ידמה שרמז בה לקדשי הקדשים שינם נאכלים כי אם לזכרי כהונה שמהם הורם להשם כמו שביארנו והנותר הוא לאהרן ולבניו ואמר תרומותי לפי מה שירימו בהם בזה מתחלף למה שירימו להש' והמשל כי המורם מהמנחה היא זולת מה שמורם מהחטאת ואם הובן זה לפי הכונה השנית שזכר יהיה יותר מבואר ההבדל באלו התרומות בין קצתם קדש וקצתם קדש קדשים ואין ראוי לספק עלינו איך יקרא הכתוב קדשי בני ישראל מה שהוא קדש הקדשים וזה כי כל קדשי הקדשים קודש ואין כל קדש קדש קדשים ועוד על כל פנים צריך להודות שכבר נכלל בזה המאמר קדש קדשים אחר שזכרה התורה בפרטו זה הכלל:
@72 **זה יהיה לך מקדש הקדשים מן האש.** לפי שאמר זאת תחלה באופן כולל שב לבאר הבדל אלו התרומו' במה שיוחדו קצתם מן קצת ואמר מן האש להעיר שמן האש יזכו בו הכהנים ר"ל כי אחר שזכה המזבח בחלקו יזכו הם בחלקם וזה יורה על האמתת הביאור שביארנו במה שאמר ואני הנה נתתי לך את משמרת תרומותי:
@72 **כל קרבנם לכל מנחתם.** ר"ל הקרב לכהנים כל המנחות לפי מה שנתבארו דיניהם כמו שתי הלחם של עצרת ולחם הפנים ומנחת חוטא ומנחת נדבה:
@72 **וכל חטאתם.** זהו הקרב לכהנים מחטאת יחיד או חטאת צבור היה שיהיו עוף ולא בהמה:
@72 **ולכל אשמם.** זה הקרב לכהנים מכל אשם היה שיהיה אשם גזלות או אשם מעילה או אשם ודאי או אשם תלוי ואשם נזיר ואשם מצורע ונכלל עמו לוג שמן של מצורע שכבר היה בא עם האשם אחר שלקח המזבח חלקו מכל אחד מאלו:
@72 **קדש קדשים לך הוא ולבניך.** זה שב לכל אלו הדברים שכל אחד מהם הוא קדש קדשים לפי מה שהתבאר במקומו והם לאהרן ולבניו הנזכרים לבד או לבנותיו:
@73 **בקדש הקדשים תאכלנו.** אחשוב שיהיה הרצון בזה שיאכל אותו במדרגת קדש הקדשים שהוא נאכל במקום קדוש וזה שכבר נתבאר בספר ויקרא שאלו נאכלים במקום קדוש והנה קצת רבותינו ביארו מזה שאם לא יוכלו הכהנים לאכלו בקדש כגון שהקיפו גוים את כל העזרה הנה יותר להם לאכלו בהיכל שהוא קדש הקדשים והנה יהיה הרצון נאמרו בקדש הקדשים תאכלנו שם תוכל לאכלו לא למנוע ממנו אכילתו בקדש כי כבר נתבאר בספר ויקרא כי הוא נאכל בקדש:
@73 **קדש יהיה לך.** מגיד שאם לא יאכלנו ראוי שינהג בו קדושה ר"ל גם במה שאינו נאכל ממנו:
@74 **וזה לך תרומת מתנם וגו'.** כלל בזה חזה ושוק של שלמים ותודה והוא מה שאמר לכל תנופות בני ישראל כי היה בו תרומה ותנופה נכלל בזה גם כן המורם מאיל נזיר' כי הוא נקרא תרומה וזכר שזה נאכל לכל טהור בית הכהן היה זכר או נקבה לא לבלתי טהור ואח"כ זכר התורה במה שאמר כל חלב יצהר וכל חלב תירוש ודגן וגומ'. לפי שהתרומה אינה נוהגת אלא בדבר שנגמרה מלאכתו כגון דגן תירוש ויצהר ובזה נכללה תרומה מעשר וזאת התרומה נקראת ראשית כמו שאמר דגנך תירושך ויצהריך ראשיתם אשר תתנו לה' כלל בה עם אלו הדברים הנזכרים חלה כי היא נקראת ראשית ותנתן לכבוד השם ואפשר לאומר שיאמר שכבר נכללו בזה גם כן ראשית הגז כי היא נקראת ראשית בפרשת שופטים והזרוע והלחיים והקבה כי הן כמו ראשיות לדברים שלוקחו מהן כמו שנבאר בג"ה בפרשת שופטים ולזה נזכרו שם שאר הדברים המתוארי' בשהם ראשיו' כמו ראשית דגן תירוש ויצהר וראשית הגז וכבר אמרו ז"ל בספרי אמנם יתבאר שהו' לא דבר בכאן מראשית גז כי אמר בסוף כל טהור בביתך יאכלנו ואין ראשית הגז נאכל ולזה יהיה אמרו ראשיתם אשר תתנו להשם שם אל חלב יצהר ולא חלב תירוש ודגן ר"ל התרומה ולזה לא יכלל בזה הזרוע והלחיים והקבה לפי הפשט וכלל החלה בזה כי הוא מחלב דגן והוא גם כן ראשית בכורי כל אשר בארצם למדנו מזה שהבכורי' הם מתנה לכהנים והוא מבואר שהקדושה חלה בבכורים אם קרא להם שם אף על פי שלא נגמרה מלאכתם כי לא נאמר בהם דגן תירוש ויצהר כמו העניין בתרומה ולא עוד אלא אפילו קרא להם שם במחובר לקרקע קדושה חלה עליהם וזה מבואר ממה שהישרנו אליו ורז"ל למדו זה מזה הפסוק רוצה לומר שאף על פי שהוא בארצם נקרא בכורים וראוי שלא יעלם ממנו כי הכונה בזאת המצוה לתת בכורים מהפירות ששבח בהם ארץ ישראל במה שספרה התורה ארץ חטה ושעורה וגפן ותאנה ורמון ארץ זית שמן ודבש והוא דבש תמרים כי דבש הדבורים אינו מיוחס לארץ אך הדבורים יחדשוהו ולזה רמז באמרו כל אשר בארצם ר"ל כי מהפירות המיוחדים לארצם על צד השבח יביאו בכורים לא מזולתם וזה יתבאר יותר ממה שנזכר מזה בפרשת והיה כי תבא שהיה אומר מביא בכורים כמו שנבאר שם בג"ה:
@76 **כל טהור בביתך יאכלנו.** מגיד שאין התרומ' והחלה והבכורי' נאכלים בטומאה ולא הוצרך להזכיר זה בקדש הקדשים כי הדברים ק"ו וראוי שיספק מספק איך כפלה התורה זה התנאי לזכור אותם במורם מקדשים קלים ואחר זה שבה לזכרו בתרומה וחלה ובכורים וכבר יספיק שתזכור אותו פעם אחת לבד לכל אלו הדברים אחר שאין הבדל ביניהם בזה התנאי ונאמ' כי אנחנו לא נסכים שלא יהיה הבדל בין טהור הנזכר בחלה ותרומה ובכורים ובין טהור הנזכר במורם מקדשי' קלים אבל הוא מבוא מההדרגה אשר זכרה בה התורה ענין אלו קדשים בגדול החלה ובקטן כלה שהענין כתנאי אכילתם הוא גם כן בזאת ההדרגה ולזה החמירה יותר באכילת קדשי הקדשים שלא יאכלו מהם כי אם הזכרים ובקדש ולא הוצרך להזכיר שלא יאכלוהו בטומאה כי בקדש אי אפשר שיכנסו טמאים שם עם שהדברים ק"ו כמו שזכרנו ואח"כ התנה במורם מקדשים קלים שלא יאכל מהם כי אם טהור היה זכר או נקבה וכן התנית באכילת תרומה חלה ובכורים ולזה הוא מבואר שהטהרה הנזכרת באכילת המורם מהקדשי' היא למעלה מהטהר' הנזכרת באכילת תרומ' וחלה ובכורי' ולפי שמצאנו בתורה ב' מינים מהטהרה האחרת ידענו שהטהרה היותר שלמה היא אשר תצטרך לאכילת המורם מהקדשים ושלמטה ממנו תצטרך לאכילת תרומה וחלה ובכורי' והנה הטהרה היותר שפלה שנזכרה לאכילת הקדשים היא הערב השמש באמרו ובא השמש וטהר ואחר יאכל מן הקדשים והיא תהיה לאכילת תרומה וחלה ובכורים ולזה גם כן אמר כי לחמו הוא והטהרה היותר שלמה ההיא אחר הערב שמש בהבאת הכפרה כמו שמצאנו ביולדת שגם אחר שטבלה והעריבה שמשה הוזהרה מנגיעת קדשים עד מלאת ימי טהרה ולא תצא מזאת הטמאה לאלו הקדשים עד שתביא כפרתה כאמרו וכפר עליה הכהן וטהרה ולזה הוא מבואר שזאת הטהרה תצטרך לאכילת המורם מהקדשים קלים ובכאן הותר זה הספק:
@78 **כל פטר רחם.** ר"ל הראשון שפתח הרחם בלידתו והוא הבכור ולמדנו מזה שאם היה הראשון יוצא דופן הנה הבא אחריו דרך הרחם הוא הבכור לזה העניין לכל בשר אשר יקריבו להשם הוא בכור שור וכבש ועז כי בהם לבד נוגע זה העניין ר"ל עניין הבכורה וענין ההקרבה כי מזולתם מהבהמות לא יקריבו כמו שהתבאר בראש ספר ויקרא:
@78 **באדם ובבהמה לך יהיה.** ר"ל כל פשר רחם באדם ובבהמה והרצון בבהמה בהמה טמאה והוא החמור לבדו כמו שהתבאר בפרשת בא אל פרעה ולזה לא הקפידה התורה לבאר זה בזה המקום:
@78 **אך פדה תפדה את בכור וגו'.** ביאר שאין קדושת אלו כקדושת בהמה אשר יקריבו ממנה קרבן לה' היא קדושה קדושת הגוף ואלו קדושים קדושת דמים וזה כי בכור האדם יפדה ה' שקלים כמו שנתבאר במה שקדם והנה השקל הוא כ' גרה והוא מעה משקל היה אז מפורסם וזה המשקל היה נותן בפדיונו בכסף צרוף כי לא יקרא כסף על האמת מה שהיה בו ערוב מתכת אחר ובכור הבהמה הטמאה היה נפדה בשה כאמרו ופטר חמור תפדה בשה והנה הקלה התרה בזכירת מה שיפדה בו כי סמכה על מה שזכרה מזה במה שדם עם שלא יהיה הדבר הכרחי שיגיע הפדיון לכהן כמו העניין בשאר המתנות שזכר וזה שכבר אפשר שלא יפדוהו הבעלים ולא יהיה בזה תועלת לכהן אבל יערוף פטר חמור אם ירצה ולא יפדהו כמו שאמר ואם לא תפדה וערפתו ולזה לא הקפידה התורה מאד בזכירת הדבר שיפדה בזה המקום שזכר בו מתנות כהונה. והנה התנית התורה בבכור אדם שיפדה אחר היותו בן חדש לפי שהבכור ראוי שיתבאר מעניינו שיהיה שלם ההויה כרחם כי היוצא מהרחם לפי הנהוג ובאופן השלם לא יהיה כי אם בזה האופן ולזה יהיה הנפל פטור מהבכורה כי לא נשלמה חויתו ואי אפשר בו גם כן שיהיה והנה לא נתבאר מהולד שלא יהיה נפל אם לא אחר היותו בן חדש כי כבר נתאמ' בנסיון כי לא יחיה הנפל ל' יום ועוד יתבאר זה מהדבר שעליו באה זאת המצוה והיא מכת בכורות והמתתם וזה לא יתכן שיאמר בנפל כי הוא כמו מת ולא יתכן לומר שהמית השם ית' המת ומזה בעינו יתבאר שלא ינהג דין בכורה בבהמה טמאה בנפל כי בכלם נאמר פטר רחם כמו שביארנו והנה למדו רבותינו ז"ל מזה המקום שהבעלים מטפלין בבכור בהמה טמאה שלשים יום אמ' שמקיש אדם לבהמה במה שאמר באדם ובבהמה מה בכור אדם מטפל בו שלשים יום אף בכור בהמה מטפל שלשים יום ולמדו מזה גם כן שהלוים פטורים מבכור בהמה שנאמר באדם ובבהמה את שיש לך בו באדם יש לך בו בבהמה יצאו הלוים שאין להם באדם לא יהיה להם בבהמה וזה מבואר בזולת ביאור מהמקו' שלמדנו ממנו שהלוים פטורים מבכור אדם לפי שהן פטרו את בכורות ישראל כמו שנזכר בפרשת במדבר סיני כ"ש שיהיו פטורי' בכוריהן ובזה יתבאר שבהמות שלהן פטורות מן הבכורה כי הם פטרו בכורות בהמתם של ישראל כ"ש שיפטרו בכורות בהמותיהם בעצמם:
@80 **אך בכור שור או בכור כשב או עז לא תפדה קדש הם.** זהו להזהיר שלא יפדה בכור בהמה טהורה ומגיד שאם פדאו אינו פדוי לפי שהוא קדש וקדוש קדושת הגוף וכן מצאנו במעשר בהמה בסוף פרשת אם בחקותי והחמיר שם יותר והוא שאם ימירנו והיה הוא ותמורתו קודש והנה היה לו לומר קודש הוא אך הוא אמר קדש הם לפי מה שזכרו רז"ל להעיר שה הדין ינהג בכל מה שקדוש קדושת הגוף כמו הפסח והמעשר וכן מה שאמר את דמם תזרוק על המזבח ואת חלבם תקטיר ויקשה לפי הפשט לפי זה הביאור ממה שאמר אחר זה ובשרם יהיה לך כחזה התנופה וכשוק הימין כי זה בלתי אפשר שישוב כי אם לבכור ולזה נאמר אנחנו כי אמרו קדש הם שב לאלו השלשה מינים מבכור רוצה לומר בכור שור וכבש ועז:
@80 **ואת דמם זרוק על המזבח.** לפי שלא אמר על קרנות למדנו שאין טעון אלא זריקה אחת וזה דבר לא ימנע ממנו אחד מהקרבנות כמו שאמר בפרשת ראה אנכי ודם זבחיך ישפך על מזבח השם אלהיך וגומ' וכבר אמר תחלה רק קדשיך אשר יהיו לך וגו'. וזה יכלול בלי ספק הפסח והמעשר. רוצה לומר מעשר בהמה ועליהם גם כן יתכן יותר שיאמר והבשר תאכל כי הבשר כלו הוא לבעלים ולזה למדנו מזה שהפסח והמעשר טעונין שפיכה אחת. ולזה גם כן דקדקה התור בפרשת ראה בזביחת הפסח שתהיה במקום אשר יבחר יי' כדי שיהיה הדם למזבח וכבר נלמד מזה המקום שפסח והמעשר הם גם כן טעונין הקטר חלבי' כמו העניין בבכור כי לזאת הבה היו קדש לש' מצד החלק שאוכל מהם המזבח והדברים גם כן קל וחומר אם הכהנים שזכו בבכור והוא ממונם הוכרחו מפני היות וקדש שיהיה המזבח אוכל חלק ממנו כ"ש בקדשי ישראל שיחוייב להם שיהיה המזבח אוכל ממנו אם לא יהיה בכאן צד יהיה בו קדש והמשל כי הלחמים היו קדש כי חלק מהם נאכל למזבח וחלק אחר נאכל לכהנים אבל הפסח והמעשר למה זה יהיו קדש כי הם כלם לבעלים ולא יהיה מהם חלק למזבח ולא לכהנים ואם אמ' אומר שמעשר שני נקרא קדש אף על פי שאין בו חלק לשם יתע' ולא לכהנים אמרנו שההבדל מבואר בין קדושת מעשר בהמה ובין קדושת מעשר שני כי מעש' שי יש רשות לבעלים לגאול אותו ואין העניין כן במעשר בהמה כי היא בעצמה קדש כמו שהתבאר בסוף פרשת אם בחקותי ולזה אי אפשר במעשר בהמה שיגאל כי בו חלק לגבוה וכבר נלמד זה גם כן ממה שאמר בפרש ראה אנכי שכלל בו אלו הקדשים כמו שזכרנו כי תמצא ששתק שם מזכירת החלב בעולה ואמר ועשית עולותיך הבשר והדם על מזבח ה' אלהיך והנה היה החלב גם כן קרב למזבח ואחר כך אמר ודם זבחיך ישפך על מזבח יי' אלהיך והבשר תאכל למדנו שאין הבעלים זוכין אלא בבשר ונשען כשלא זכר החלב להשענו שזה ידוע שחלבי הזבחים הם כלם למזבח ולזה לא מצא ההבדל בין העולה והזבחים כי אם בבשר שבשר העולה הוא למזבח ובשר הזבחים הוא לבעלים:
@81 **ובשרם יהיה לך כחזה התנופה וגומר.** למדנו מזה שהבכור נאכל לב' ימים ולילה אחד כמו העניין בחזה ושוק של שלים ואין לאומר שיאמר שיהיה רצון התורה בזה בחזה ושוק של תודה שאינם נאכלים כי אם ליום ולילה אחד וזה כי מצאנו בשפיכת הדם שהשלמים הם למעלה מהבכור כי הם טעונין שתי מתנות שהם ארבע והבכור אינו טעון כי אם מתנה אחת ולזה ראוי שנתפש בזמנו זמן השלמים לא זמן התודה ולזאת הסבה גם כן יתבאר שזמן אכילת מעשר בהמה הוא ב' ימים ולילה אחד כשלמים כי הוא זמן הנתן לאכילת היותר קל שבקדשי':
@82 **כל תרומות הקדשי' אשר ירימו בני ישראל לה' לך נתתים ולבניך ולבנותיך אתך לחוק עולם.** ר"ל שהמורם משלמים ותודה ואיל נזיר אחר שזכה המזבח בחלקו כי אלו נאכלם לזכרים ולנקבות ושב להזכיר בזה המקום זה הענין דרך כלל:
@82 **ברית מלח עולם הוא לפני ה'.** הנה המלח ייוחד שאינו נסד גם שומר מההפסד הדברים שיומלחו בו ולזה אמר להורות על הקיום לזה הברית שהוא ברית מלח ולזה סמך לו לעולם להורות על המצחיות ואמר לפני יי' להעיר שזה הברית יתקיים מה שיתמיד הש' יתעלה להיות קיים כטעם לו ישמעאל יהיה לפניך לפי מה שביארנו שם וככה כונת יהי שמו לעולם לפני שמש ולפני ירח דור דורים:
@83 **בארצם לא תנחל וגו'.** זה אמנם היה מיושר התורה כי די להם באלו המתנות למה שיצטרך להם למחיתם וכן הענין בלויים רוצה לומר שדי להם במעשר שנותנים להם ישראל מכל תבואותיהם למחיתם והיתה כונת התורה בזה שלא יהיו אלו טרודי' במזונותיהם ויהיה להם פנאי לעסוק בתור ולהזכיר את בוראם ואמנם היו להם ערים לשבת כי בזולת זה אי אפשר להן ועם שבענין נתינת המעשר הערה להשיג השם יתעלה והנה היה בענינו מהיושר בנתינת זה השעור ישראל ללוים כי הוא חלק קרוב למה שהיה ראוי להם מנחלת הארץ לפי מספר השבטים ומזה יתבאר שחובה לישראל לתת המעשר מפירותיהם ללוים שלא תאמר שאי זה מישראל שיפריש מעשר הוא ללוי' ואם רצה יפריש ואם לא יפריש כאמרו כל חרם בישראל לך יהיה שאם רצה מחרים ואם לא רצה אינו מחרים וזה שאם היה הדבר כן אולי לא יהיה שם מי שיפריש מעש' ויעדר מזו הלוי' ולא יהיה זה גמולם הראוי להם על עבודת' ה' ית':
@84 **ולבני לוי הנה נתתי את כל מעשר בישראל לנחלה חלף עבודתם.** מגיד שאם עבד יטול ואם לא עבד לא יטול מכאן אמר בן לוי שקבל עליו עבודת הלוים חוץ מדבר אחד שאין לו חלק בלויה וכבר התבארו אופני עבודת הלוים במה שקדם:
@85 **ולא יקרבו עוד בני ישראל אל אהל מועד.** ר"ל לעבוד עבודה וזו היא אזהרה שלא יקרב זר:
@85 **לשאת חטא למות.** מגיד שזר שעבד חייב מיתה בידי שמים ובזה יהיו ישראל נצולים ממה שפחדו ממנו באמרם כל הקרב הקרב אל משכן השם יומת וגו'. וזה כי כבר בחר השם ית' באהרן ובזרעו בזאת העבודה ובלויי' בעבודה המיוחדת להם:
@86 **ועבד הלוי הוא עבודת אהל מועד.** זו היא מצות עשה שיעבדו הלוים העבודה המיוחדת להם:
@86 **והם ישאו את עונם.** ר"ל במה שיחטאו בזאת העבודה וישראל יהיו נקיים מזה החטא:
@86 **ובתוך בני ישראל לא ינחלו נחלה.** רוצה לומר שלא יהיה להם חלק בארץ לפי שיש להן מעשר פירות בכל תבואות שאר השבטים כמו שזכר בפסוק אחר זה:
@87 **אשר ירימו ליי' תרומה.** ר"ל עשר פירות אשר הרימו מהם תרומה גדולה:
@87 **נתתי ללוי' לנחלה.** לפי שזאת הנחלה היא תמורת חלק נחלתם בארץ ונחלת הארץ נוהגת בין בפני הבית בין שלא בפני הבית כן לקיחת הלוי' מעשר ראשון מישראל מפירות הארץ נוהגת בין בפני הבית בין שלא בפני הבית וזה מבואר חיובו:
@89 **והרמותם ממנו תרומת יי'.** הנה יתבאר ממה שאמר ממנו שלא יתרום ממין על שאינו מינו ולפי שבמעשר ראשון דקדקה התורה שלא יעשרו מן החדש על הישן ולא מן הישן על החדש שנאמר עשר תעשר את כל תבואת זרעך היוצא השדה שנה שהוא מבואר שיותר ראוי לדקדק בזה בתרומות מעשר זה גם כן יתבאר מאמרו ממנו ויתבאר גם כן שהמעשר אינו נוהג אלא בפירות הארץ ממה שאמר בסוף פרשת אם בחקותי וכל מעשר הארץ מזרע הארץ ולזה גם כן יתבאר מאמרו ממנו שאין מעשרין מפירות חוצה לארץ על פירות ארץ. והנה קרא אותם תרומת ה' להורות שהוא קדש:
@90 **ונחשב לכם תרומתכם כדגן הגרן וכמלאה מן היקב.** ר"ל שהם דברים שנגמרה מלאכתן אבל לא יתרומו שבלים על החטים וזתים על שמן כמו הענין בתרומה שמפרישין ישר' לתת לכהנים כי הוא בדבר שנגמרה מלאכתו ולפי שכבר צוה אותם בזה המאמר להפריש תרומת מעשר אחר שנגמרה מלאכתו והיה לחושב שיחשוב שאם לקח הלוי מישראל מעשר ראשון קודם שנגמרה מלאכתו שלא נתן עדיין הישראל תרומה גדולה לכהן שכבר יפטר הלוי כשיתן לכהן תרומה מעשר לבד ויפטר מתרומה גדולה אמר כן תרימו גם אתם תרומת יי' וגומ' ר"ל שלא תחשבו שאינכם מחוייבים בתרומה גדולה לפי שאתם לויים ולא חייבה אתכם התור כי כן בודאי גם כן מחוייבים להפרישה אחר שלא הופרשה ביד הישראל וגמר מלאכת הפירות ההם בידיכם ותתנו התרומה לאהרן הכהן ולפי שהתרומות הם בכללם לאהרן ולבניו כמו שנתבאר במה שקדם הנה אין ראוי שנבין מזה המקום שלא יתנו הלוים ואת התרומה כי אם לכהן גדול אבל נבין מזה המקום שהוא קודם לבניו כמו שבארנו במה שקדם וכבר למדו' רבותי' ז"ל מזה שאין ראוי לתת' כי אם לכהן חבר כמו הענין באהרן לא לכהן עם הארץ וזה באמת דבר ראוי לכל המתנות כאמרו לתת מנה לכהנים למען יחזקו בתורת ה' ויתבאר מזה שהמחזיקים בתורת השם הם אשר יש להם כמו שארז"ל:
@92 **מכל מתנותיכם תרימו תרומה וגו'.** אחר שביאר שאם הקדים הלוי לקחת המעשר קודם שנגמרה מלאכת הפירות ההם שהוא חייב לתת לכהן תרומה גדולה מלבד תרומת מעשר ביאר שם שאם היה שיתנו להם ישראל מפירותיהם קודם שנגמרה מלאכתם מלבד המעשר הנה גם מהמתנות ההם יחוייב ללוים לתת כל תרומת ה' הראויה להם אחר שנגמר מלאכתם כי אין הנתנ' ללוים פוטר הפירות ההם מתרומה גדולה והנה הוצרך לבאר זה כי אולי יחשוב חושב כי מה שנתחייבו בו בתרומת מעשר יתחייבו גם כן בתרומה גדולה אחר שהערים הלוי והקדים לקחת המעשר בשבולים אבל מה שנתן ללוים שאינו מעשר יפטר מתרומה גדולה כי התורה לא צותה זה כי אם לישראל ולזה באר שגם בזה חייב הלוי לתת תרומה גדולה זהו הביאור שנראה לנו בזה והו' נאות מאד לפי מה שנחשוב להמלט שלא יהיה בזאת הפרשה כפל דברים ללא תועלת:
@92 **מכל חלבו את מקדשו.** הנה קרא חלבו הפרי שנגמרה מלאכתו שהוא נקי מהפסולת והוא מקדשו הקדש שיש בו שאוסרו ומקדש אותו והכונה בזה מבוארת ממה שקדם. ואמרת אליהם בהרימכם את חלבו וגו'. זה שב אל המעשר ראשון שזכר תחלה וזהו אמרו אחר זה כי שכר הוא לכם חלף עובדתכם והרצון בזה שכאש' תרימו ממנו מעשר שנגמר' מלאכתו אז יחשב הנשאר ללוים כתבואת גורן וכתבואת יקב לישראל שאין בו שום קדוש' אך קודם זה לא יותר להם לאכל ממנו כי הוא בלתי מתוקן ומקדשו הוא בתוכו וזהו אמרו ואכלתם אותו בכל מקום ר"ל אפילו חוץ לירושלם ואפילו במקום טמא כי אין בו שום קדושה:
@95 **ולא תשאו עליו חטא וגו'.** מזה התבאר שאם לא ירימו ממנו תרומת מעשר ישאו עליו חטא באכלם אותו בטבלו ויהיו חייבים מיתה בידי שמים כי הם מחללים קדשי בני ישראל בנהגם בהם מנהג חולין ולזה הוא מבואר שאף על פי שנטמא המעשר הם חייבים להפריש ממנו תרומת מעשר כדי שלא ישאו עליו חטא. ובכאן נשלם הביאור בזאת הפרשה.

@1 ואולם התועלות המגיעות ממנה הנה הם כ"א:
@1 **התועלת** הראשון הוא בדעות והוא שאין ראוי לחלוק עם הגדולים ממנו הלא תראה מה שקרה לקרח מפני מחלוקתו עם משה רבינו אדון הנביאים:
@1 **התועלת** השני הוא במדות והוא שאין ראוי שיקנא האדם בכבוד ומעלה שיש לזולתו יותר ממנו אבל ראוי שיספיק לו מה שחננו השם תעלה מזה וזה כי קרח מפני קנאתו במעלה והכבוד שנתן השם יתעלה לאהרון היה סבה אל שפתה אנשים רבים מישראל ומשכם אליו בה המחלוקת וגרם זה האבוד לו ולהם:
@1 **התועלת** השלישי הוא במדות והוא להודיע שהוא ראוי למנהיג כי כשיראה שהמונהגים ממנו מתיצבים על דרך לא טוב שישתדל בחכמתו להשיבם לטוב ולא יכעס עליהם וגם אם הם בועטים בו הלא תראה איך השתדל משה לפייס קרח בדברים גבוהים בישוב ובזולת כעס במה שהראה לו מדבריו שחננו השם יתעלה מהכבוד והמעלה בעבור אשר נתנה ללוים עבודת אהל מועד ולשבח השם יתע' בשיריהם עם שכבר נתעלה משפחתו בזאת העבודה על שאר משפחות הלוים עלוי רב להיות עבודת בני קהת בקדש הקדשים ואין הענין כן בבני גרשון ובני מררי וכבר הראה לו עם זה ג"כ כי זה לא היה בבחירת אהרן כי מהשם יתעלה נתנה לו הכהונה ולזה היה ראוי שלא יחזיקו עוד בזה המחלוקת ולזאת הסבה בעינה תמצא שקרא משה לדתן ולאבירם לפייסם מפני ידיעתו כי הם היו סבה חזקה לזה המחלוקת ואולי אם יתפייסו הם יהיו זה סבה שיתפייס קרח וינצלו כלם מהעונש:
@1 **התועלת** הרביעי הוא במדו' והוא להודיע שראוי לאדם כשיראה רצון האנשים ברע שיעתיקם מהרע ההוא מעט מעט כי אם רצה להעתיקם יחד ממנו הנה הם לא ישמעו לא לחוזק הסתבכם ברצון ההוא ולזה תמצא שכאשר רצה משה להעתיק קרח ועדתו מהרע שבחרו בו הקדים להם ממה שיה אפשר אצלם שישיגו מבוקשם בו והוא אמרו שהשם יתע' יבחר מי הוא הקדוש הראוי לכהנה עם מה שהיתה מהחכמה בזה המאמר כי הוא הראה להם שמהשם יתעלה נהיה הדבר הזה ולזה יהיה לשוא חלקם עליו וזה היה מיתרון מעלת משה וחכמתו שכבר כלל זה המאמר מה שיתפייסו בו תחלה לפי שלא התיאשו ממבוקשם ואח"כ יתבאר להם מהדברים ההם בעצמם עם מה שהמשיך להם מהמאמרים שיהיה בהם מהפיוס מאד מה שהיה ראוי שיעתיקם בשלמות מהרצון הרע שנשקעו בו ולזאת הסבה נפל משה על פניו לפני קרח לבקש ממנו שלא יחזיק בזה העניין:
@1 **התועלת** החמישי הוא בדעות והוא להודיע שלא תועיל התפילה והקרבת המנחה ליי' להשיג מה שאין ראוי שיושג לפי היושר כי כל דרכיו משפט ולזה תמצא ששפט משה שהשם יתעלה לא יפנה אל מנחת האנשים האלה כי הם מתרעמים ממשה על מה שאין ראוי להתרעם בו כי הוא לא הרע להם בצד מהצדדים ולזה לא היה להם לבעוט בו כ"ש שכבר הטיב להן מאד השם יתעלה על ידו:
@1 **התועלת** הששי הוא בדעות והוא להודיע עניין נפלא בדבר ההשגחה האלהית והו' שהעם המתאחד והיו לאגדה אחת שדבקה בהן ההשגחה הפרטית מהשם יקרה להם כשיחטא איש אחד מהם או אנשים מעטי המספר שיזוקו כלם כשתסור ההשגחה מהם וזה כבר ראוי והמשל שאם היה מלך אחד אוהב שר אחד והיה השר ההוא נלחם עם אדון מה והבטיחו המלך לעזרו במלחמתו ונקשר עם השר ההוא איש אחד שונאו לזה המלך הנה יסור עזר המלך ההוא מזה השר בעבור האיש ההוא שהוא שונאו ולזאת הסבה תמצא שעכן לבדו מעל בחרם ועל כל העדה היה קצף ולזאת הסבה תמצא בזה המקום שבעבור חטא קרח היה השם יתעלה רוצה לכלות ישראל לולא תפלת משה ואהרן:
@1 **התועלת** השביעי הוא בדעות והוא להודיע כי תפלת הנביא הדבק בשם יתעלה תסיר הרע מזולתו כשיקשה בעיניו זה כי בעבור השגחת השם יתעלה בו ישמרהו מזה הצער שיצטער אם ישיג הרע לאיש ההוא או לנשים ההם ולזה תמצא שתכף שהתפללו משה ואהרן על ישראל שב חרון אף השם יתעלה מהם:
@1 **התועלת** השמיני הוא בדעות והוא להודיע שהשם יעלה משגיח ומנהיג נפשות כל אחד מהאנשים ואין השגחתו נתלית בכללות המין לבד כמו שחשב הפילוסוף וזה הוא שאמר אל אלהי הרוחות לכל בשר ויהיה הרצון בזה הנה אתה השם יתעלה אשר השגחתך באיש איש בפרט מצד רוחו ושכלו היתכן שבעבור הכללות וההשתתפו' ישיג רע לכל העדה בעבור חטא איש אחד ולפי שהיה בלתי אפשר זולת זה כמו שקדם אם לא יסור ההשתתפות וההתאחדות מאלו החטאים עם ישראל לקח השם יתעלה עצה בזה כשיסתלקו ישראל סביב משכן אלו האנשים ויסור מפני זה השתתפותם והתאחדותם עמהם עם שזה יהיה סבה שלא יפותו להמשך לעצתם הרעה:
@1 **התועלת** התשיעי הוא לפרסם ענין זה המופת הנפלא שיהיה בפתיחת הארץ את פיה לבלוע אלו החטאים תכף שהשלים משה אלו הדברים שיתאמת בהם כי מהשם היתה זאת כי בהאמנת המופתים קיום אמונת התורה בכללה ויותר נפלא מזה שוב הארץ תכף לעניינה הראשון ר"ל שכסת עליהם הארץ כי פתיחת הארץ פיה כשהיה על דרך הטבע ישאר הפתח ההוא זמן ארוך מאד אך בכאן היו שני מופתים האחד בהמצאת הפתיחה ברגע מה שלא ישלם על דרך הטבע כי אם בזמן ארוך מאד והשני בסלוק זה המציאות וזה דומה לשאר מופתים נתנו זה המנהג כמו שוב המטה נחש ואחר זה שב הנחש מטה ושוב היד מצורעת ואחר זה שבה תכף בבשרו והנה זה התועלת בעינו הוא במה שזכר מהמופת ביציאת אש מאת ה' לאכול את חמשים ומאתים איש מקריבי הקטרת ובמטה אהרן שהוציא פרח ויצץ ציץ ויגמול שקדים:
@1 **התועלת** העשירי הוא להודיע שמי שירצה לחלוק על עניין המעלה והכבוד שגזר השם יתעלה לאיש מהאנשים כל מה שישתדל לחלוק עניין המעלה עליו יוסיף לו שלמות וקיום הלא תראה כי הערעור שערער קרח על הכהונה היה סבה אל שתהיה הכהונה ביותר שלם ממה שהיתה לאהרן ולבניו כי זה היה סבה לבאר לכל ישראל שהזר הקרב יומת בידי שמים ושהכהונה היא לאהרן מהשם יתעלה לא מבחיר' משה באופן שאי אפשר שיפול ספק לאיש מהאנשים ולזה היתה המצוה מהשם יתעלה לעשות המחתות מהאנשים החטאים ההם רקועי פחים צפוי למזבח להשאיר זכר זה הענין לדורות למען אשר לא יקרב איש זר אשר לא מזרע אהרן הוא להקטיר קטורת לפני השם פן יקרה לו דמיון מה שקרה לאלו החטאים ולזה הושם גם כן מטה אהרן שהוציא פרח וצץ צי וגמל שקדים לפני העדו' למשמרת לדורות להשאיר זכר זה העניין:
@1 **התועלת** הי"א הוא במדות והוא להודיע כי ראוי למנהיג השלם להשתדל בשמירת המונהגים ממנו בתכלית מה שאפשר ואף על פי שהם בועטים בו לא יתרשל מהצלתם הלא תראה כי היה מרוע תכונת ישראל להתרעם על משה ועל אהרן מהרע שקרה לחטאים שקמו כנגדם שהיו הם בעצמם סבה להגעתו ועם זה גם כן השתדל משה להצילם ממנו ולהעתיקם מהרצון הרע ההוא לפי היכולת וזה ממה שהיה ראוי שימנעם מהתרעם על משה מזה העניין ועם כל זה כשראה משה שבעיטתם בו היתה סבה אל שיצא הקצף מלפני השם לכלותם מהר להשתדל בהצלתם ולזה צווה אהרן להקטיר קטרת מרה להסיר הנגף מהעם.
@1 **התועלת** הי"ב הוא להסיר החשד שאפשר לישראל שיחשדו שיהיה טבע הקטרת להמית המקטירים אותו עד שאולי היו תולים בזה מיתת החמשים ומאתים איש מקריבי הקטרת ולא יודו שיהיה על דרך המופת מהשם יתעלה ולזה שם הכלי בהצלתם הקטרת כדי שיתאמת להם שלא היה זה העניין מטבע הקטרת אך מהשם יתעלה היתה נסבה בעבור חטאם בזאת ההקרבה:
@1 **התועלת** הי"ג הוא לבאר לישראל עוצם ההבדל שיהיה בין האיש הנבחר שבחר בו השם יתעלה להיות כהן ובין האנשים האלו שתקרבו מעצמם לדבר כהונה כי אלו המיתו עצמם בהקטרת הקטרת ואהרן הציל מהמות כל ישראל והקטרתו הקטורת וזה היה סבה להוסיף אמות בלב ישראל כי מהשם היתה הכהונה לאהרן ולבניו:
@1 **התועלת** הי"ד הוא במצות והוא המצוה בשמירת המקדש והתועלת בזאת המצוה מבואר להוסיף מעלה וחשיבות לבית המקדש בלב ישראל וזה היה סבה אל שלא יקלו בו וייראו ממנו וזה יהיה מבא להעמידנו על אופן החכמה שהיה בענייני זה הבית הנכבד אשר ינהגו בו בזה הכבוד והקדושה עם שזה יהיה כלי לשמירת ישראל שייראו מהכשל בענין המקדש והעבודות והנעשות בו:
@1 **התועלת** הט"ו הוא במצות והוא מה שהזהירה התורה שלא יקרבו זרים לעבודת בית המקדש ושאם יקרב לה ישיגהו עונש המות והנה היה התועלת בזאת המצוה כי העבודות האלו היו מעידות על עניינים עמוקים מאד והוא המכוון כמו שביארנו בספר ויקרא וכאשר תונח לאלו העבודות משפחה מיוחדת לזאת העבודה והיה לחמם נתן ומימיהם נאמנים בדרך שיהיה להן פנאי בעיון ותהיה מגמת פניהם להשתדל בעניין השלמות האנושי כמו העניין במשפחת בני אהרן היה בזה הישרה אל שיעמדו על סודות זאת העבודה הנכבדת עם מה שהישירו בזה קצתם את קצת כ"ש כשהיה הראשון מהם באופן מהשלמות שהיה בו והיו אבותיו כלם אנשים גדולים מאד כי זה יהיה סבה ליתרון ההכנה אבל השלמות בזרע אהרן כי טבע המקור הוא נמצא במה שנחצב ממנו ואלו היה קרב לזאת העבודה כל מי שירצה היה סבה להחטיא כוונת התורה בעניין זאת העבודה הנכבדת עד שכבר יעשו אותה ולא יעמדו על סודה ויהיה זה גם כן סבה אל שיקלו בה ויקרה בזה מההפסד בה מה שלא יעלם:
@1 **התועלת** הי"ו הוא במצות והוא מה שצותה התורה שיעבדו הלוים במקדש העבודה המיוחדת להם לא זולתם והנה התועלת בזאת המצוה הוא מסוג התועלת המצוה אשר לפניה:
@1 **התועלת** הי"ז הוא במצות והוא האזהרה שלא להתעצל משמירת המקדש ותועלת זאת המצוה מבואר ממה שקדם עם שבו תועלת לשמור ישראל מהכשל בעניני המקדש כמו שהתבאר מזה המקום:
@1 **התועלת** הי"ח הוא להודיע מה שסדרה התור' מהמתנו' לכהנים וללוים כדי שיהיה להם פנאי לעסוק בתורה ולעמוד על סודות המציאות לפי מה שאפשר ולזאת הסבה בעינה גם כן לא רצתה התורה שיהיה להם חלק ונחלה בארץ כדי שלא יהיו טרודים בעבודת האדמה ויהיה זה סבה להעדר השלמות מהם ובזה היה תועלת בעניין העבודות שהיו עובדים כמו שזכרנו ועוד בו תועלת להשאיר השלמות בזה העם הנבחר עד שלא יתכן בעת מהעתים שלא ימצא בזה החלק ממנו כאמרו לא תאבד תורה מכהן ואמר יורו משפטיך ליעקב ותורתך לישראל ואמר כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו:
@1 **התועלת** הי"ט הוא במצות והוא מה שהזהירה התורה שלא יקרבו הלוים לעבודת הכהנים ולא זה לעבודת זה והנה התועלת בזאת המצוה במעט עיון ממה שזכרנו בתועלת הט"ו מאלו התועלות:
@1 **התועלת** כ' הוא במצות והוא האזהרה שהוזהרנו מלפדות בכור בהמה טהורה והנה התועלת בזאת המצוה הוא כי התורה רצתה שיהיה קדוש קדושת הגוף להשאיר זכר המופת הנפלא שעשה השם יתעלה בעניין מכת בכורות ולו היה אפשר שיפדה היה הבא לכהן איננו בכור ויחלש מפני זה זה הזכרון עם שזה יהיה סבה אל שיקלו בנתינתו לכהן ויעכבוהו לעצמם להחשבם שזה העניין הוא לדמים לבד ויענו שבעת מה יפרעוהו לכהנים כאשר תמצא ידם כי הרבה יקלו האנשים בענין הממון שנתחייבו בו כ"ש כשלא היו לו תובעין כמו העניין במתנות כהונה ואולם בבכור פטר חמור לא היה אפשר בו זולת זה כי לא יתכן שיהיה קדושתו קדושת הגוף עם שהתורה התחכמה שעכ"פ יפדוהו הבעלים לפי שאסור להן ליהנות בפטר חמור אם לא יפדוהו אבל יחוייב להם לערפו אם יש בעניינו מהזרות מה שיביאו הבעלים לפדותו ואולם בבכור אדם לא היה אפשר בו יותר כי אי אפשר שיהיה קדוש קדושת הגוף ואיננו נכון שתצוה התורה בהמתתו כמו שצותה בהמתה בפטר חמור:
@1 **התועלת** הכ"א הוא במצות והוא מה שנצטוו הלויים להפריש תרומת מעשר והוא מעשר מן המעשר והנה התועלת בזאת המצוה מבואר בכללות ממה שזכרנו במתנות כהונה ובה עוד תועלת להעיד על מה שיעיר עליו עניין המעשר וכבר ביארנו זה התועלת במה שקדם:

@96 **ואולי** לזאת הסבה סבב שמואל לחדש המלוכה בגלגל כאילו הראה שעד עתה לא היה מלך בשלמות:
@97 ואמר לפני ה' בגלגל כי שם בנו מזכח וזבחו בו ובראשונ' היה שם המשכן כמו שנזכר בספר יהושע בתחלתו, ואחר זה השתדל שמואל להביא את ישראל ומלכם אל שיתנהגו בדרכי התורה ולא יסורו ממנה וזכר להם תחלה שכל ימיו הנהיגם בדרכי התורה מאין נשא פנים לאדם ולא לקחם שום דבר לא על צד העושק ולא באופן אחר והעיד להם זה בפני ה' ובפני שאול כאילו יהיה השם יתעלה לעד ביניהם על זה ושאול משיחו עד שהם הודו שהאמת כן הוא כמו שאמר שמואל:
@103 והנה אמר שמואל ה' שעשה את משה ואת אהרן לעוצם השגחתו על ישראל ואשר העלה את אבותיכ' מארץ מצרים רצה בזה כי ה' שעשה כל זה יהיה לעד ביניהם, או אמר זה על צד ההודעה והרצון בו ה' הוא אשר עשה כל זה להשגחתו על זה וזה נגלה מצד האותות והמופתים שנתחדשו אז וזה יותר נכון ויותר נקשר למה שאחריו, ואחר זה הרחיב הביאור בחסדים שעשה הש"י לישראל וקצר מזה לפרסומו כי לא זכר יהושע שהנחיל להם את הארץ ולא זכר גם כן מהשופטים שהקים הש"י להם כי אם ד' ולא זכר השופט שהצילם מיד סיסרא עם שכבר זכר מה שמכרם הש"י לסיסרא וידמה שלא זכר אלו הארבעה כי אם לבאר להם שמרוב חסדי השם יתברך היה שהושיע את ישראל מאויביהם פעם על יד הבלתי שלמים מאד אף על פי שלא היו ראויים לזה מצד עצמם כמו הענין בירובעל ויפתח כי ירובעל היה עובד ע"א כשקרא השם אליו להושיע את ישראל ויפתח גם כן לא ראינו לו מעלה כי אם בגבורה ופעם הושיעם על יד השלמים מאד כמו הענין בבדן ושמואל וזה כי בדן שהוא שמשון מצאנו לו מהשלמות שכבר עשה הש"י מופת על ידו וכאשר קרא אל ה' ענהו וזה הורה על שלמותו והיותו באופן מה במדרגת הנביאים כי המופתים לא יעשה הש"י רק על יד הראוי כמו שבארנו בששי מספר מלחמות ה' ואולם שלמות שמואל הוא מבואר מאד וזה היה מעוצם ההשגחה האלהית בישראל כי כשהיה אפשר שיהיה ביניהם איש שלם ראוי שיעשה נס על ידו הקימוהו עליהם לשופט והושיעם על ידו וכשלא היה ביניהם איש בזה התאר הושיעם ג"כ על יד בלתי שלם ואם אינו ראוי לכך מצד יתרון השגחתו על ישראל וכאילו אמר זה להורות להם כי לא יצטרכו למלך להלחם מלחמותיהם כי ה' אלהי ישראל הוא מלכם ויושיעם כאשר ישובו אליו כמו שעשה בימי השופטים ששלח להם שופטים להושיעם ואם יסורו מדרכי התורה לא יועיל להם המלך אבל תהיה יד ה' בהם כמו שהיתה באבותיהם שלא היה להם מלך:
@114 הלא קציר חטים. והנה הראה שמואל לעם אות כי חטאו מאד לה' כששאלו להם מלך ואמר הלא קציר חטים היום אקרא אל ה' ויתן קולות ומטר ואמנם אמר זה כי קציר חטים היה שם סביב חג השבועות והנה העת הוא אז לפי הטבע חם ולא גם התקופה שעברה היתה בטבעה קרה ולחה ולא יתכן על המנהג הטבעי שיהיו שם אז אידים עשניים יתהוו מהם הרעמים והברקים וזהו האות שנתן לפי מה שאחשוב שאם לא היה שם אות זולת נתינת הקולות והמטר כשקרא שמואל אל ה' לא היה צריך לומר הלא קציר חטים היום, ואפשד שנאמר הלא קציר חטים היום היה להורות על צחות האויר כי האנשים היו קוצרים חטים וזה יורה על היות העת ההוא בלתי מעונן ובלתי ראוי למטר, והנה הביאור הראשון יותר נכון לפי מה שאחשוב, והנה הרגישו העם בזה האות והודו כי חטאו מאד כששאלו להם מלך, ואחר זה היישירם שמואל באמצעות זה הפעל אל שיתנהגו בדרכי התורה ולא יסורו מאחרי השם יתעלה כי הסר מאחריו הולך אחרי התהו אשר לא יועילו ולא יצילו:
@119 **והודיע** כי הש"י לא יטוש עמו בעבור שמו הגדול ולזה הוא משגיח עליהם בזה האופן והנפלא שזכר:
